kernel_flavor() {
  local k
  k="$(uname -r 2>/dev/null || true)"
  # e.g. 4.4.0-210-generic → generic
  case "$k" in
    *-generic) printf 'generic' ;;
    *-generic-lpae) printf 'generic-lpae' ;;
    *-lowlatency) printf 'lowlatency' ;;
    *) printf '%s' "${k##*-}" ;;
  esac
}

avail_bytes() {
  local path="$1"
  df -B1 --output=avail "$path" 2>/dev/null | tail -1 | tr -d ' ' || df -B1 "$path" | awk 'NR==2{print $4}'
}

write_state() {
  local st="$1"
  local dest
  dest="$(hostpath "$STATE_FILE")"
  mkdir -p "$(dirname "$dest")"
  printf '%s\n' "$st" | durable_atomic_write "write_state" "$dest" || {
    log ERROR "DURABLE_WRITE_RESULT=FAIL logical=write_state path=${dest}"
    return 1
  }
}

read_state() {
  local f
  f="$(hostpath "$STATE_FILE")"
  if [[ -f "$f" ]]; then
    tr -d '\r' <"$f" | head -1
  else
    printf ''
  fi
}

ensure_log_dir() {
  mkdir -p "$(hostpath "$(dirname "$LOG_FILE")")"
  touch "$(hostpath "$LOG_FILE")" 2>/dev/null || true
}

decode_embedded_assets() {
  local work="$1"
  mkdir -p "$work"
  b64_decode_to_file "$PIN_KEY_B64" "$work/stellar-offline-upgrade.gpg"
  b64_decode_to_file "$PIN_MANIFEST_KEY_B64" "$work/stellar-offline-manifest.gpg"
  b64_decode_to_file "$PIN_META_B64" "$work/meta-release-lts"
  b64_decode_to_file "$PIN_MANIFEST_B64" "$work/client-manifest.json"
  b64_decode_to_file "$PIN_MANIFEST_SIG_B64" "$work/client-manifest.json.asc"
  b64_decode_to_file "$PIN_ANNOUNCEMENT_B64" "$work/ReleaseAnnouncement"
}

verify_embedded_trust() {
  local work="$1"
  local h fpr
  h="$(sha256_file "$work/stellar-offline-upgrade.gpg")"
  [[ "$h" == "$PIN_KEY_SHA256" ]] || die "$EC_TRUST" "embedded repository key SHA256 mismatch"
  h="$(sha256_file "$work/stellar-offline-manifest.gpg")"
  [[ "$h" == "$PIN_MANIFEST_KEY_SHA256" ]] || die "$EC_TRUST" "embedded manifest key SHA256 mismatch"
  h="$(sha256_file "$work/meta-release-lts")"
  [[ "$h" == "$PIN_META_SHA256" ]] || die "$EC_TRUST" "embedded meta-release SHA256 mismatch"
  h="$(sha256_file "$work/client-manifest.json")"
  [[ "$h" == "$PIN_MANIFEST_SHA256" ]] || die "$EC_TRUST" "embedded manifest SHA256 mismatch"

  # repository key fingerprint (apt / InRelease)
  fpr="$(gpg --no-default-keyring --keyring "$work/stellar-offline-upgrade.gpg" --with-colons --fingerprint 2>/dev/null \
    | awk -F: '/^fpr:/ {print $10; exit}')"
  fpr="$(printf '%s' "$fpr" | tr '[:lower:]' '[:upper:]')"
  [[ "$fpr" == "$PIN_KEY_FINGERPRINT" ]] || die "$EC_TRUST" "repository key fingerprint mismatch: got ${fpr}"

  fpr="$(gpg --no-default-keyring --keyring "$work/stellar-offline-manifest.gpg" --with-colons --fingerprint 2>/dev/null \
    | awk -F: '/^fpr:/ {print $10; exit}')"
  fpr="$(printf '%s' "$fpr" | tr '[:lower:]' '[:upper:]')"
  [[ "$fpr" == "$PIN_MANIFEST_KEY_FINGERPRINT" ]] || die "$EC_TRUST" "manifest key fingerprint mismatch: got ${fpr}"

  # Reject unsigned-test placeholders. Marker is split so production client
  # artifacts contain zero contiguous unsigned-test literals for grep gates.
  _unsigned_test_marker="UNSIGNED""_TEST"
  if grep -Fq "$_unsigned_test_marker" "$work/client-manifest.json.asc" 2>/dev/null; then
    if [[ -z "$TEST_ROOT" ]]; then
      die "$EC_TRUST" "manifest signature is ${_unsigned_test_marker} - rebuild with signing key"
    fi
    log WARN "TEST_ROOT set: accepting ${_unsigned_test_marker} manifest signature"
  else
    gpgv --keyring "$work/stellar-offline-manifest.gpg" \
      "$work/client-manifest.json.asc" "$work/client-manifest.json" \
      || die "$EC_TRUST" "manifest signature verification failed"
  fi

  # meta-release must not reference external hosts
  if grep -qiE '(archive|security|old-releases|changelogs)\.ubuntu\.com|api\.snapcraft\.io' \
      "$work/meta-release-lts"; then
    die "$EC_META" "embedded meta-release contains external URL"
  fi
}

verify_mirror_trust_chain() {
  local work="$1"
  local repo="${MIRROR_BASE}/hops/${PIN_HOP}/ubuntu"
  local tmp code
  # Root-private work dir for embedded-asset fetches (NOT the APT sandbox root).
  tmp="$(mktemp -d /tmp/stellar-offline-private.XXXXXX)"
  # TCP/80
  code="$(http_code "${MIRROR_BASE}/")"
  # 200/403/404 acceptable for root; connection failure is 000
  [[ "$code" != "000" ]] || die "$EC_MIRROR" "mirror unreachable: ${MIRROR_BASE}"

  local suite
  for suite in $PIN_SOURCE_SUITES; do
    code="$(http_code "${repo}/dists/${suite}/Release")"
    [[ "$code" == "200" ]] || die "$EC_MIRROR" "Release missing for suite ${suite} (HTTP ${code})"
    code="$(http_code "${repo}/dists/${suite}/InRelease")"
    [[ "$code" == "200" ]] || die "$EC_MIRROR" "InRelease missing for suite ${suite} (HTTP ${code})"
  done
  for suite in $PIN_TARGET_SUITES; do
    code="$(http_code "${repo}/dists/${suite}/Release")"
    [[ "$code" == "200" ]] || die "$EC_MIRROR" "target Release missing for suite ${suite} (HTTP ${code})"
  done

  # Packages index (main always present in this selective hop)
  code="$(http_code "${repo}/dists/${PIN_SOURCE_CODENAME}/main/binary-amd64/Packages.gz")"
  [[ "$code" == "200" ]] || die "$EC_MIRROR" "Packages.gz missing (HTTP ${code})"

  code="$(http_code "${PIN_SAMPLE_DEB_URL}")"
  [[ "$code" == "200" ]] || die "$EC_MIRROR" "sample .deb unreachable: ${PIN_SAMPLE_DEB_URL}"

  local up_tar="${MIRROR_BASE}/offline/release-upgraders/bionic/bionic.tar.gz"
  local up_gpg="${up_tar}.gpg"
  code="$(http_code "$up_tar")"
  [[ "$code" == "200" ]] || die "$EC_MIRROR" "upgrader tar unreachable"
  code="$(http_code "$up_gpg")"
  [[ "$code" == "200" ]] || die "$EC_MIRROR" "upgrader gpg unreachable"

  http_fetch "$up_tar" "${tmp}/bionic.tar.gz"
  http_fetch "$up_gpg" "${tmp}/bionic.tar.gz.gpg"
  [[ "$(sha256_file "${tmp}/bionic.tar.gz")" == "$PIN_UPGRADER_TAR_SHA256" ]] \
    || die "$EC_TRUST" "upgrader tar SHA256 mismatch"
  [[ "$(sha256_file "${tmp}/bionic.tar.gz.gpg")" == "$PIN_UPGRADER_GPG_SHA256" ]] \
    || die "$EC_TRUST" "upgrader gpg SHA256 mismatch"

  # InRelease signature
  http_fetch "${repo}/dists/${PIN_SOURCE_CODENAME}/InRelease" "${tmp}/InRelease"
  gpgv --keyring "$work/stellar-offline-upgrade.gpg" "${tmp}/InRelease" \
    || die "$EC_TRUST" "repository InRelease signature verification failed"
  log INFO "APT_INRELEASE_SIGNATURE=PASS"

  # Temporary apt update using only local hop (no persistent changes).
  # Dedicated _apt-accessible APT root (shared helper); never nest under 0700 private tmp.
  if [[ -z "$TEST_ROOT" ]]; then
    run_temporary_local_apt_authentication_preflight \
      "$work/stellar-offline-upgrade.gpg" "$repo" "$PIN_SOURCE_SUITES" "$PIN_COMPONENTS"
  fi

  # Optional HTTP meta-release on /client/ - warn if absent (embedded copy is authoritative)
  code="$(http_code "${MIRROR_BASE}/client/${PIN_HOP}/meta-release-lts")"
  if [[ "$code" == "200" ]]; then
    http_fetch "${MIRROR_BASE}/client/${PIN_HOP}/meta-release-lts" "${tmp}/meta-http"
    [[ "$(sha256_file "${tmp}/meta-http")" == "$PIN_META_SHA256" ]] \
      || die "$EC_META" "HTTP meta-release SHA256 mismatch vs pin"
  else
    log INFO "Optional HTTP meta-release unavailable (HTTP ${code}); using verified embedded meta-release"
    log INFO "HTTP_META_RELEASE=NOT_PUBLISHED"
    log INFO "HTTP_META_RELEASE_STATUS=${code}"
    log INFO "META_RELEASE_SOURCE=EMBEDDED_SIGNED_COPY"
  fi

  rm -rf "$tmp"
}

check_os_baseline() {
  # Phase 1 OS identity/safety only - product version/topology are not hard gates.
  local arch kflav
  arch="$(dpkg --print-architecture 2>/dev/null || uname -m)"
  [[ "$arch" == "amd64" || "$arch" == "x86_64" ]] || {
    log ERROR "FAIL_UNSUPPORTED_BASELINE: architecture=${arch}"
    return 1
  }
  kflav="$(kernel_flavor)"
  log INFO "kernel=$(uname -r) flavor=${kflav}"
  case "$kflav" in
    generic|generic-lpae) ;;
    *)
      log ERROR "FAIL_UNSUPPORTED_BASELINE: kernel flavor '${kflav}' (discovery baseline expects generic)"
      return 1
      ;;
  esac
  # Required kernel packages presence (names only)
  if [[ -z "$TEST_ROOT" ]]; then
    if ! dpkg-query -W -f='${Status}\n' "linux-image-generic" 2>/dev/null | grep -q 'install ok installed'; then
      # accept versioned image matching running kernel
      local kr
      kr="$(uname -r)"
      if ! dpkg-query -W -f='${Status}\n' "linux-image-${kr}" 2>/dev/null | grep -q 'install ok installed'; then
        log ERROR "FAIL_UNSUPPORTED_BASELINE: required kernel image package missing"
        return 1
      fi
    fi
  fi
  # foreign architectures
  if [[ -z "$TEST_ROOT" ]] && command -v dpkg >/dev/null 2>&1; then
    local foreign
    foreign="$(dpkg --print-foreign-architectures 2>/dev/null || true)"
    if [[ -n "$foreign" ]]; then
      log ERROR "FAIL_UNSUPPORTED_BASELINE: foreign architectures present: ${foreign}"
      return 1
    fi
  fi
  # DKMS modules → WARNING (OS safety signal; not a product gate)
  if [[ -d "$(hostpath /var/lib/dkms)" ]] && find "$(hostpath /var/lib/dkms)" -mindepth 1 -maxdepth 1 2>/dev/null | grep -q .; then
    log WARN "WARNING_REQUIRES_CONFIRMATION: DKMS modules present under /var/lib/dkms"
    BASELINE_WARNINGS=1
  fi
  return 0
}

# Backward-compatible name used by older tests/docs.
check_baseline() {
  check_os_baseline "$@"
}

check_dpkg_health() {
  if [[ -n "$TEST_ROOT" ]]; then
    [[ ! -f "$(hostpath /tmp/dpkg-broken)" ]] || return 1
    return 0
  fi
  if dpkg --audit 2>/dev/null | grep -q .; then
    log ERROR "dpkg --audit reported issues"
    return 1
  fi
  if [[ -f /var/lib/dpkg/lock ]] && ! flock -n /var/lib/dpkg/lock true 2>/dev/null; then
    # flock may not exist; fallback fuser
    if command -v fuser >/dev/null 2>&1 && fuser /var/lib/dpkg/lock >/dev/null 2>&1; then
      log ERROR "dpkg lock held"
      return 1
    fi
  fi
  local lists_lock="/var/lib/apt/lists/lock"
  if [[ -f "$lists_lock" ]] && command -v fuser >/dev/null 2>&1 && fuser "$lists_lock" >/dev/null 2>&1; then
    log ERROR "apt lists lock held"
    return 1
  fi
  if command -v apt-get >/dev/null 2>&1; then
    if ! apt-get check >/dev/null 2>&1; then
      log ERROR "broken dependencies (apt-get check failed)"
      return 1
    fi
  fi
  return 0
}

pkg_installed_version() {
  local pkg="$1"
  dpkg-query -W -f='${Version}' "$pkg" 2>/dev/null || true
}

is_bionic_version_for_pkg() {
  # Return 0 if version looks like a Bionic (18.04) core package.
  local pkg="$1" ver="$2"
  [[ -n "$ver" ]] || return 1
  case "$pkg" in
    base-files) [[ "$ver" == 10.* ]] && return 0 ;;
    libc6|libc-bin) [[ "$ver" == 2.27* ]] && return 0 ;;
    apt|apt-utils) [[ "$ver" == 1.6* ]] && return 0 ;;
    dpkg) [[ "$ver" == 1.19* ]] && return 0 ;;
    systemd|systemd-sysv|udev) [[ "$ver" == 237* || "$ver" == *237* ]] && return 0 ;;
    python3) [[ "$ver" == 3.6* ]] && return 0 ;;
    ubuntu-server) [[ "$ver" == 1.417* ]] && return 0 ;;
    ubuntu-minimal|ubuntu-standard) [[ "$ver" == 1.417* ]] && return 0 ;;
    linux-image-*|linux-headers-*|linux-generic|linux-virtual|linux-image-generic|linux-image-virtual)
      [[ "$ver" == 4.15* || "$ver" == *4.15* ]] && return 0
      ;;
    ubuntu-release-upgrader-core|update-manager-core)
      # Bionic upgrader packages often carry 1:18.04 in version
      [[ "$ver" == *18.04* || "$ver" == 1:18* ]] && return 0
      ;;
  esac
  return 1
}

detect_partial_release_transition() {
  # Fail-closed when os-release is still Xenial but core packages look Bionic,
  # or dpkg is dirty / unfinished dist-upgrade package mutation remains.
  # A FAILED state alone (e.g. MetaRelease config parse) is NOT partial transition.
  local ver codename mixed=0
  ver="$(read_os_field VERSION_ID)"
  codename="$(read_os_field VERSION_CODENAME)"
  [[ -z "$codename" ]] && codename="$(read_os_field UBUNTU_CODENAME)"

  if [[ -n "$TEST_ROOT" ]]; then
    if [[ -f "$(hostpath ${STATE_ROOT}/force-partial-transition)" ]]; then
      log ERROR "FAIL_PARTIAL_RELEASE_TRANSITION_DETECTED (test fixture)"
      die "$EC_PARTIAL_TRANSITION" "FAIL_PARTIAL_RELEASE_TRANSITION_DETECTED"
    fi
    return 0
  fi

  if [[ "$ver" == "$PIN_SOURCE_VERSION" || "$codename" == "$PIN_SOURCE_CODENAME" ]]; then
    local pkg ivers
    for pkg in base-files libc6 apt dpkg systemd systemd-sysv; do
      ivers="$(pkg_installed_version "$pkg")"
      if is_bionic_version_for_pkg "$pkg" "$ivers"; then
        log ERROR "mixed core package: ${pkg}=${ivers} on SOURCE_OS=${ver}"
        mixed=1
      fi
    done
  fi

  if dpkg --audit 2>/dev/null | grep -q .; then
    log ERROR "dpkg audit dirty during partial-transition check"
    mixed=1
  fi
  if has_upgrade_transaction_evidence; then
    local st
    st="$(read_state)"
    if [[ "$st" == "FAILED" || "$st" == "PREPARING_XENIAL" || "$st" == "UPGRADING_XENIAL_TO_BIONIC" ]]; then
      log ERROR "unfinished dist-upgrade transaction evidence under /var/log"
      mixed=1
    fi
  fi

  if [[ "$mixed" -eq 1 ]]; then
    PARTIAL_RELEASE_TRANSITION="YES"
    log ERROR "FAIL_PARTIAL_RELEASE_TRANSITION_DETECTED"
    die "$EC_PARTIAL_TRANSITION" "FAIL_PARTIAL_RELEASE_TRANSITION_DETECTED"
  fi
  PARTIAL_RELEASE_TRANSITION="NO"
  return 0
}

check_critical_package_holds() {
  # Phase 1 planned-unhold: read-only classify. Never unhold here.
  # Critical OS holds → PASS_WITH_PLANNED_ACTION. Product holds → INFO only.
  reconcile_critical_hold_state
  classify_held_packages

  if [[ -n "$DETECTED_PRODUCT_HOLDS" ]]; then
    log INFO "PRODUCT_HOLD_IGNORED_PHASE1: ${DETECTED_PRODUCT_HOLDS}"
  fi

  if [[ -z "$PLANNED_CRITICAL_OS_HOLDS" ]]; then
    log INFO "CRITICAL_OS_HOLDS_DETECTED="
    log INFO "CRITICAL_OS_HOLD_ACTION=NONE"
    log INFO "CRITICAL_OS_HOLD_PREFLIGHT=PASS"
    return 0
  fi

  log INFO "CRITICAL_OS_HOLDS_DETECTED=${PLANNED_CRITICAL_OS_HOLDS}"
  log INFO "CRITICAL_OS_HOLD_ACTION=UNHOLD_AFTER_CONFIRMATION"
  log INFO "CRITICAL_OS_HOLD_PREFLIGHT=PASS_WITH_PLANNED_ACTION"
  log INFO "CRITICAL_OS_HOLDS_REMAIN_UNHELD_THROUGH_OS_UPGRADE=YES"
  log INFO "CRITICAL_OS_HOLDS_RESTORED_ON_PRE_TRANSITION_FAILURE=YES"
  log INFO "CRITICAL_OS_HOLDS_AUTO_REHOLD_AFTER_SUCCESS=NO"
  return 0
}

print_execution_plan() {
  cat <<EOF

------------------------------------------------------------
 Execution plan (Phase 1 OS-only)
------------------------------------------------------------
Source OS: ${PIN_SOURCE_VERSION} (${PIN_SOURCE_CODENAME})
Target OS: ${PIN_TARGET_VERSION} (${PIN_TARGET_CODENAME})
Mirror:    ${MIRROR_BASE}
EOF
  if [[ -n "$PLANNED_CRITICAL_OS_HOLDS" ]]; then
    cat <<EOF

Critical OS holds to be removed:
EOF
    local pkg
    # shellcheck disable=SC2086
    for pkg in $PLANNED_CRITICAL_OS_HOLDS; do
      printf -- '- %s\n' "$pkg"
    done
    cat <<EOF

NOTE: Removing these holds is a persistent package selection change.
Critical OS holds are removed for the release upgrade. If failure occurs
before package transition starts, the original holds are restored. After a
successful OS upgrade they are not automatically re-held.
EOF
  else
    cat <<EOF

Critical OS holds to be removed: (none)
EOF
  fi
  if [[ -n "$DETECTED_PRODUCT_HOLDS" ]]; then
    cat <<EOF

Product package holds (kept; not unheld in Phase 1):
EOF
    local pkg
    # shellcheck disable=SC2086
    for pkg in $DETECTED_PRODUCT_HOLDS; do
      printf -- '- %s\n' "$pkg"
    done
  fi
  cat <<EOF
------------------------------------------------------------
EOF
}

check_cross_release_candidates() {
  # Read-only: private APT lists against SOURCE suites only; never mutates host sources.
  local tmp repo sim candidates=0
  tmp="$(mktemp -d /tmp/stellar-cross-release-XXXXXX)"
  # shellcheck disable=SC2064
  trap "rm -rf '$tmp'" RETURN
  mkdir -p "$tmp/lists/partial" "$tmp/cache/archives/partial" "$tmp/etc/apt/apt.conf.d"
  repo="${MIRROR_BASE}/hops/${PIN_HOP}/ubuntu"
  {
    local s
    for s in $PIN_SOURCE_SUITES; do
      printf 'deb [arch=amd64] %s %s %s\n' "$repo" "$s" "$PIN_COMPONENTS"
    done
  } >"$tmp/sources.list"
  # Host dpkg status is used so candidates reflect upgrades of installed packages.
  local apt_opts=(
    -o "Dir::Etc::sourcelist=$tmp/sources.list"
    -o "Dir::Etc::sourceparts=/dev/null"
    -o "Dir::State=$tmp/lists"
    -o "Dir::State::Lists=$tmp/lists"
    -o "Dir::Cache=$tmp/cache"
    -o "Dir::Cache::Archives=$tmp/cache/archives"
    -o "APT::Get::AllowUnauthenticated=false"
    -o "Acquire::Languages=none"
  )
  if [[ -f "$(hostpath "$LEGACY_APT_KEYRING_PATH")" ]]; then
    apt_opts+=(-o "Dir::Etc::TrustedParts=$(hostpath /etc/apt/trusted.gpg.d)")
  elif [[ -f "$KEYRING_PATH" ]]; then
    apt_opts+=(-o "Dir::Etc::Trusted=$KEYRING_PATH")
  fi
  if ! apt-get "${apt_opts[@]}" update >/dev/null 2>"$tmp/update.err"; then
    log ERROR "cross-release guard: apt-get update failed"
    cat "$tmp/update.err" >&2 || true
    die "$EC_CROSS_RELEASE" "FAIL_CROSS_RELEASE_CANDIDATE_BEFORE_UPGRADER"
  fi

  # Policy check on core packages.
  # Buffer apt-cache output first - never pipe into awk with early exit under pipefail
  # (SIGPIPE/rc=141 would silently abort the outer client via set -e).
  local pkg cand policy_out policy_rc
  for pkg in $CORE_GUARD_PACKAGES; do
    set +e
    policy_out="$(apt-cache "${apt_opts[@]}" policy "$pkg" 2>/dev/null)"
    policy_rc=$?
    set -e
    [[ "$policy_rc" -eq 0 ]] || continue
    cand="$(awk '/^[[:space:]]*Candidate:/{print $2; exit}' <<<"$policy_out")"
    [[ -n "$cand" && "$cand" != "(none)" ]] || continue
    if is_bionic_version_for_pkg "$pkg" "$cand"; then
      log ERROR "cross-release candidate: ${pkg} Candidate=${cand}"
      candidates=$((candidates + 1))
    fi
  done
  # Also scan linux image/header metapackages that may be installed
  local inst
  inst="$(dpkg-query -W -f='${Package}\n' 'linux-image-*' 'linux-headers-*' 2>/dev/null || true)"
  for pkg in $inst; do
    set +e
    policy_out="$(apt-cache "${apt_opts[@]}" policy "$pkg" 2>/dev/null)"
    policy_rc=$?
    set -e
    [[ "$policy_rc" -eq 0 ]] || continue
    cand="$(awk '/^[[:space:]]*Candidate:/{print $2; exit}' <<<"$policy_out")"
    [[ -n "$cand" && "$cand" != "(none)" ]] || continue
    if is_bionic_version_for_pkg "$pkg" "$cand"; then
      log ERROR "cross-release candidate: ${pkg} Candidate=${cand}"
      candidates=$((candidates + 1))
    fi
  done

  apt-get "${apt_opts[@]}" -s dist-upgrade >"$tmp/sim-dist.txt" 2>"$tmp/sim-dist.err" || true
  apt-get "${apt_opts[@]}" -s -f install >"$tmp/sim-f.txt" 2>"$tmp/sim-f.err" || true
  if grep -Eiq 'base-files \(.*10\.|libc6 \(.*2\.27|apt \(.*1\.6|dpkg \(.*1\.19|systemd \(.*237|python3 \(.*3\.6|linux-.*\(.*4\.15' \
    "$tmp/sim-dist.txt" "$tmp/sim-f.txt" 2>/dev/null; then
    log ERROR "simulated dist-upgrade/-f install would pull target-release packages"
    candidates=$((candidates + 1))
  fi

  log INFO "SOURCE_OS=${PIN_SOURCE_VERSION}"
  log INFO "SOURCE_CODENAME=${PIN_SOURCE_CODENAME}"
  log INFO "SOURCE_REPOSITORY_RELEASE=${PIN_SOURCE_CODENAME}"
  log INFO "TARGET_CODENAME=${PIN_TARGET_CODENAME}"
  log INFO "CROSS_RELEASE_CANDIDATES=${candidates}"
  if [[ "$candidates" -gt 0 ]]; then
    log ERROR "PRE_UPGRADER_PACKAGE_GUARD=FAIL"
    die "$EC_CROSS_RELEASE" "FAIL_CROSS_RELEASE_CANDIDATE_BEFORE_UPGRADER"
  fi
  log INFO "PRE_UPGRADER_PACKAGE_GUARD=PASS"
  return 0
}

run_os_preflight() {
  local work="$1"
  BASELINE_WARNINGS=0

  log_phase1_banner

  # Read-only OS identity/baseline checks first - no persistent mutation until they pass.
  [[ "$(id -u)" -eq 0 || -n "$TEST_ROOT" ]] || die "$EC_ROOT" "root required"

  require_cmds bash curl gpg gpgv apt-get dpkg systemctl sha256sum base64 awk sed grep

  local pretty version_id codename arch
  pretty="$(read_os_field PRETTY_NAME)"
  version_id="$(read_os_field VERSION_ID)"
  codename="$(read_os_field VERSION_CODENAME)"
  [[ -z "$codename" ]] && codename="$(read_os_field UBUNTU_CODENAME)"
  if [[ "$version_id" != "$PIN_SOURCE_VERSION" || "$codename" != "$PIN_SOURCE_CODENAME" ]]; then
    # Allow completed bionic re-entry handled by caller
    die "$EC_OS" "OS must be Ubuntu ${PIN_SOURCE_VERSION} (${PIN_SOURCE_CODENAME}); got VERSION_ID=${version_id} CODENAME=${codename} (${pretty})"
  fi
  log INFO "SOURCE_SERIES_MATCH=PASS"

  arch="$(uname -m)"
  [[ "$arch" == "x86_64" ]] || die "$EC_ARCH" "architecture must be amd64/x86_64 (got ${arch})"

  check_os_baseline || die "$EC_BASELINE" "OS baseline validation failed"

  # Product diagnostics only - never hard-fail Phase 1 on DP install/topology/version.
  if is_stellar_dp; then
    log INFO "DP_HOST_IDENTITY=PRESENT"
  else
    log INFO "DP_HOST_IDENTITY=ABSENT"
    log INFO "DP_HOST_IDENTITY_ACTION=IGNORED_BY_PHASE1_POLICY"
  fi
  log_product_state_phase1

  write_state "PREFLIGHT"

  local adata
  adata="$(hostpath /opt/aelladata)"
  if [[ ! -d "$adata" ]]; then
    # State root lives under /opt/aelladata; create only the upgrade state path parent in fixtures.
    if [[ -n "$TEST_ROOT" ]]; then
      mkdir -p "$adata"
      log INFO "DP_AELLADATA_CREATED_FOR_STATE_TEST=1"
    else
      die "$EC_DP" "/opt/aelladata missing (required for upgrade state root)"
    fi
  fi
  if [[ -z "$TEST_ROOT" ]]; then
    findmnt -T /opt/aelladata >/dev/null 2>&1 || log INFO "could not confirm mount for /opt/aelladata"
  fi

  if [[ -z "$TEST_ROOT" ]]; then
    local root_avail boot_avail ad_avail
    root_avail="$(avail_bytes /)"
    boot_avail="$(avail_bytes /boot)"
    ad_avail="$(avail_bytes /opt/aelladata)"
    ((root_avail >= MIN_ROOT_BYTES)) || die "$EC_DISK" "insufficient root space: ${root_avail} < ${MIN_ROOT_BYTES}"
    ((boot_avail >= MIN_BOOT_BYTES)) || die "$EC_DISK" "insufficient /boot space: ${boot_avail} < ${MIN_BOOT_BYTES}"
    ((ad_avail >= MIN_AELLADATA_BYTES)) || die "$EC_DISK" "insufficient /opt/aelladata space: ${ad_avail} < ${MIN_AELLADATA_BYTES}"
  elif [[ -f "$(hostpath /tmp/force-disk-fail)" ]]; then
    die "$EC_DISK" "insufficient disk space (test fixture)"
  fi

  check_dpkg_health || die "$EC_DPKG" "dpkg/apt health check failed"

  detect_partial_release_transition

  if [[ "$(read_state)" == "READY_FOR_RESUME" ]]; then
    verify_prior_critical_hold_resume_consistency
    log_idempotent_prep_states
  fi

  check_critical_package_holds

  # NTP / time - informational only if unsynchronized
  if command -v timedatectl >/dev/null 2>&1; then
    if ! timedatectl status 2>/dev/null | grep -qiE 'NTP synchronized: yes|System clock synchronized: yes'; then
      log INFO "NTP_SYNC=UNCONFIRMED (informational; not a Phase 1 hard gate)"
    fi
  fi

  # Stub-pin fixtures skip live mirror/GPG so OS-only preflight can PASS in tests.
  if [[ -n "$TEST_ROOT" && ( "$PIN_KEY_FINGERPRINT" == "DEADBEEF" || "${DP_OFFLINE_FAKE_MIRROR_TRUST:-}" == "1" ) ]]; then
    log INFO "MIRROR_TRUST_GATE=SKIPPED_TEST_FIXTURE"
    log INFO "SOURCE_OS=${PIN_SOURCE_VERSION}"
    log INFO "SOURCE_CODENAME=${PIN_SOURCE_CODENAME}"
    log INFO "SOURCE_REPOSITORY_RELEASE=${PIN_SOURCE_CODENAME}"
    log INFO "TARGET_CODENAME=${PIN_TARGET_CODENAME}"
    log INFO "CROSS_RELEASE_CANDIDATES=0"
    log INFO "PRE_UPGRADER_PACKAGE_GUARD=PASS"
  else
    verify_embedded_trust "$work"
    verify_mirror_trust_chain "$work"

    # Cross-release candidate guard (read-only APT simulation against local hop)
    if [[ -z "$TEST_ROOT" ]]; then
      check_cross_release_candidates
    else
      log INFO "SOURCE_OS=${PIN_SOURCE_VERSION}"
      log INFO "SOURCE_CODENAME=${PIN_SOURCE_CODENAME}"
      log INFO "SOURCE_REPOSITORY_RELEASE=${PIN_SOURCE_CODENAME}"
      log INFO "TARGET_CODENAME=${PIN_TARGET_CODENAME}"
      log INFO "CROSS_RELEASE_CANDIDATES=0"
      log INFO "PRE_UPGRADER_PACKAGE_GUARD=PASS"
    fi
  fi

  # do-release-upgrade frontend support check (xenial)
  if [[ -z "$TEST_ROOT" ]] && command -v do-release-upgrade >/dev/null 2>&1; then
    if ! do-release-upgrade --help 2>&1 | grep -q -- '-f'; then
      die "$EC_CMDS" "do-release-upgrade does not document -f frontend option; refusing"
    fi
  fi

  # Deterministic local meta-release validation BEFORE destructive confirmation.
  validate_meta_release_preview "$work"

  write_state "READY_FOR_CONFIRMATION"
  log INFO "os_upgrade_result=READY_FOR_CONFIRMATION"
  log INFO "os_validation_result=PREFLIGHT_PASS"
  log INFO "product_validation_result=NOT_RUN_PHASE1"
  log INFO "preflight PASS (warnings=${BASELINE_WARNINGS})"
  return 0
}

preflight() {
  # Phase 1 entry: OS preflight only. Product preflight is intentionally not called.
  run_os_preflight "$@"
}

run_os_upgrade() {
  # Persistent commit + runner start after confirmation (Phase 1 OS path).
  local work="$1"
  commit_and_start "$work"
}

run_os_post_upgrade_validation() {
  # Invoked conceptually by postboot verifier; kept as a named Phase 1 stage.
  log INFO "run_os_post_upgrade_validation: deferred to postboot unit"
  return 0
}

# shellcheck shell=bash
# Shared destructive confirmation helpers for offline OS upgrade clients.
# Injected into single-file clients at build / stub-render time.
# Compatible with Bash 4.3+ and safe under `set -Eeuo pipefail`.
#
# Contracts:
# - trim_outer_whitespace: strip leading/trailing space, tab, CR (and other
#   [[:space:]] characters) only; never alter interior whitespace; never log.
# - require_destructive_confirmation EXPECTED:
#     return 0 on accept, return 21 after 3 failures or EOF.
# - Never log the raw user input. Expected phrase may be re-printed.
# - Depends on caller-provided `log LEVEL message` function.

trim_outer_whitespace() {
  # Trim leading/trailing whitespace only (space/tab/CR/[[:space:]]).
  # Interior whitespace is preserved. Result is printed without a trailing newline.
  local s="${1-}"
  s="${s#"${s%%[![:space:]]*}"}"
  s="${s%"${s##*[![:space:]]}"}"
  printf '%s' "$s"
}

require_destructive_confirmation() {
  local expected="${1-}"
  local max_attempts=3
  local attempt=0
  local raw trimmed

  if [[ -z "$expected" ]]; then
    return 21
  fi

  while [[ "$attempt" -lt "$max_attempts" ]]; do
    printf 'Confirmation> '
    raw=""
    if ! IFS= read -r raw; then
      return 21
    fi

    trimmed="$(trim_outer_whitespace "$raw")"

    if [[ -z "$trimmed" ]]; then
      attempt=$((attempt + 1))
      if [[ "$attempt" -ge "$max_attempts" ]]; then
        return 21
      fi
      log WARN "Empty confirmation. No action was taken. Try again (${attempt}/${max_attempts})."
      printf 'Type exactly: %s\n\n' "$expected"
      continue
    fi

    if [[ "$trimmed" == "$expected" ]]; then
      if [[ "$raw" != "$trimmed" ]]; then
        log INFO "Leading/trailing whitespace was ignored."
      fi
      log INFO "Confirmation accepted."
      return 0
    fi

    attempt=$((attempt + 1))
    if [[ "$attempt" -ge "$max_attempts" ]]; then
      return 21
    fi
    log WARN "Confirmation mismatch. No action was taken. Try again (${attempt}/${max_attempts})."
    printf 'Type exactly: %s\n\n' "$expected"
  done

  return 21
}


prompt_confirmation() {
  print_execution_plan
  cat <<EOF

============================================================
 DESTRUCTIVE OFFLINE OS UPGRADE
============================================================
- This upgrades Ubuntu ${PIN_SOURCE_VERSION} → ${PIN_TARGET_VERSION} only
- Automatic rollback is NOT available
- Take VMware/hypervisor snapshots of master AND workers first
- On success the host will reboot automatically
- SSH sessions will be disconnected
- 18.04 → 20.04 will NOT start automatically
EOF
  if [[ -n "$PLANNED_CRITICAL_OS_HOLDS" ]]; then
    cat <<EOF
- Critical OS holds will be permanently unheld for Phase 1 (not auto-restored)
============================================================

Critical OS holds to be removed:
EOF
    local pkg
    # shellcheck disable=SC2086
    for pkg in $PLANNED_CRITICAL_OS_HOLDS; do
      printf -- '- %s\n' "$pkg"
    done
    cat <<EOF

This is a persistent package selection change.
EOF
  else
    cat <<EOF
============================================================
EOF
  fi
  cat <<EOF

Type exactly: ${PIN_CONFIRM_PHRASE}

EOF
  if [[ "$SKIP_CONFIRM" -eq 1 ]]; then
    die "$EC_CONFIRM" "SKIP_CONFIRM is not allowed outside TEST_ROOT"
  fi
  if [[ -n "$TEST_ROOT" && "${DP_OFFLINE_FAKE_CONFIRM:-}" == "$PIN_CONFIRM_PHRASE" ]]; then
    return 0
  fi
  require_destructive_confirmation "$PIN_CONFIRM_PHRASE" || die "$EC_CONFIRM" "confirmation rejected"
}

backup_persistent_config() {
  local stamp="$1"
  local dest
  dest="$(hostpath "${BACKUP_ROOT}/${stamp}")"
  mkdir -p "$dest/apt/sources.list.d" "$dest/apt/apt.conf.d" "$dest/update-manager" "$dest/passwd"
  local f
  f="$(hostpath /etc/apt/sources.list)"
  [[ -f "$f" ]] && cp -a "$f" "$dest/apt/sources.list"
  if [[ -d "$(hostpath /etc/apt/sources.list.d)" ]]; then
    cp -a "$(hostpath /etc/apt/sources.list.d)/." "$dest/apt/sources.list.d/" 2>/dev/null || true
  fi
  f="$(hostpath /etc/apt/apt.conf)"
  [[ -f "$f" ]] && cp -a "$f" "$dest/apt/apt.conf"
  if [[ -d "$(hostpath /etc/apt/apt.conf.d)" ]]; then
    cp -a "$(hostpath /etc/apt/apt.conf.d)/." "$dest/apt/apt.conf.d/" 2>/dev/null || true
  fi
  for f in release-upgrades meta-release; do
    local p
    p="$(hostpath /etc/update-manager/$f)"
    [[ -f "$p" ]] && cp -a "$p" "$dest/update-manager/$f"
  done
  if [[ -d "$(hostpath /etc/update-manager/release-upgrades.d)" ]]; then
    mkdir -p "$dest/update-manager/release-upgrades.d"
    cp -a "$(hostpath /etc/update-manager/release-upgrades.d)/." \
      "$dest/update-manager/release-upgrades.d/" 2>/dev/null || true
  fi
  getent passwd root aella 2>/dev/null >"$dest/passwd/shells.txt" || true
  # Record COMMIT_BACKUP_PATH metadata for later resume/restore identity.
  printf '%s\n' "$stamp" >"$dest/COMMIT_STAMP"
  printf '%s\n' "${BACKUP_ROOT}/${stamp}" >"$dest/COMMIT_BACKUP_PATH"
  log INFO "backup written to ${dest}"
  log INFO "COMMIT_BACKUP_PATH=${BACKUP_ROOT}/${stamp}"
}

disable_third_party_sources() {
  local stamp="$1"
  local lists dest f base
  lists="$(hostpath /etc/apt/sources.list.d)"
  dest="$(hostpath "${BACKUP_ROOT}/${stamp}/third-party")"
  mkdir -p "$dest"
  [[ -d "$lists" ]] || return 0
  for f in "$lists"/*; do
    [[ -e "$f" ]] || continue
    base="$(basename "$f")"
    case "$base" in
      *.disabled|*.bak|*.dpkg-old|*.dpkg-dist|*.save|stellar-offline-*.list) continue ;;
    esac
    # Keep only our offline list; move everything else out of scan path
    if [[ "$base" == "stellar-offline-xenial-to-bionic.list" ]]; then
      continue
    fi
    mv -f "$f" "$dest/$base"
    log INFO "disabled third-party source: $base"
  done
}

restore_noninteractive_conffile_policy() {
  # Restore preexisting apt conffile policy or remove the temporary keep-local file.
  local reason="${1:-pre_upgrade_failure}"
  local confd path bak holds
  confd="$(hostpath /etc/apt/apt.conf.d)"
  path="${confd}/97stellar-offline-conffile-policy"
  holds="$(hostpath "${HOLDS_DIR}")"
  bak="${holds}/97stellar-offline-conffile-policy.preexisting"
  mkdir -p "$confd" "$holds" 2>/dev/null || true
  if [[ -f "$bak" ]]; then
    cp -a "$bak" "$path"
    chmod 0644 "$path"
    chown root:root "$path" 2>/dev/null || true
    log INFO "NONINTERACTIVE_CONFFILE_POLICY_RESTORED=YES reason=${reason}"
  else
    rm -f "$path" 2>/dev/null || true
    log INFO "NONINTERACTIVE_CONFFILE_POLICY_REMOVED=YES reason=${reason}"
  fi
  return 0
}

install_noninteractive_conffile_policy() {
  # Atomically install keep-local dpkg/ucf policy so DistUpgrade apt/dpkg never prompts.
  local confd path tmp bak holds dump
  confd="$(hostpath /etc/apt/apt.conf.d)"
  path="${confd}/97stellar-offline-conffile-policy"
  holds="$(hostpath "${HOLDS_DIR}")"
  bak="${holds}/97stellar-offline-conffile-policy.preexisting"
  mkdir -p "$confd" "$holds"
  if [[ -f "$path" && ! -f "$bak" ]]; then
    # Preserve only non-stellar preexisting content once; never treat our own
    # managed file as an operator backup (keeps reinstall idempotent).
    if ! grep -q 'stellar offline: keep local conffiles' "$path" 2>/dev/null; then
      cp -a "$path" "$bak"
      log INFO "NONINTERACTIVE_CONFFILE_POLICY_PREEXISTING_BACKED_UP=YES"
    fi
  fi
  tmp="${path}.tmp.$$"
  cat >"$tmp" <<'EOF'
# stellar offline: keep local conffiles during unattended release upgrade
# ASCII-only. Applied to apt/dpkg invoked by do-release-upgrade.
DPkg::Options {
  "--force-confdef";
  "--force-confold";
};
EOF
  chmod 0644 "$tmp"
  chown root:root "$tmp" 2>/dev/null || true
  mv -f "$tmp" "$path"
  chmod 0644 "$path"
  chown root:root "$path" 2>/dev/null || true
  NONINTERACTIVE_CONFFILE_APT_CONFIG="/etc/apt/apt.conf.d/97stellar-offline-conffile-policy"
  export DEBIAN_FRONTEND=noninteractive
  export DEBIAN_PRIORITY=critical
  export UCF_FORCE_CONFFOLD=1
  # needrestart is Bionic+; harmless no-op on Xenial when unset/unused.
  export NEEDRESTART_MODE=a
  log INFO "CONFFILE_POLICY=KEEP_LOCAL"
  log INFO "DPKG_FORCE_CONFDEF=YES"
  log INFO "DPKG_FORCE_CONFOLD=YES"
  log INFO "UCF_FORCE_CONFFOLD=1"
  log INFO "DEBIAN_FRONTEND=noninteractive"
  log INFO "DEBIAN_PRIORITY=critical"
  log INFO "NONINTERACTIVE_CONFFILE_APT_CONFIG=${NONINTERACTIVE_CONFFILE_APT_CONFIG}"
  if command -v apt-config >/dev/null 2>&1; then
    dump="$(apt-config -c "$path" dump 2>/dev/null || true)"
    if printf '%s\n' "$dump" | grep -Fq 'DPkg::Options:: "--force-confdef"' \
      && printf '%s\n' "$dump" | grep -Fq 'DPkg::Options:: "--force-confold"'; then
      log INFO "NONINTERACTIVE_CONFFILE_POLICY_VALIDATION=PASS"
    else
      log ERROR "NONINTERACTIVE_CONFFILE_POLICY_VALIDATION=FAIL"
      die "$EC_INTERNAL" "FAIL_NONINTERACTIVE_CONFFILE_POLICY_VALIDATION"
    fi
  else
    if grep -q '"--force-confdef"' "$path" && grep -q '"--force-confold"' "$path"; then
      log INFO "NONINTERACTIVE_CONFFILE_POLICY_VALIDATION=PASS"
    else
      log ERROR "NONINTERACTIVE_CONFFILE_POLICY_VALIDATION=FAIL"
      die "$EC_INTERNAL" "FAIL_NONINTERACTIVE_CONFFILE_POLICY_VALIDATION"
    fi
  fi
}

restore_apt_sources_from_backup() {
  # Restore /etc/apt sources from pre-mutation backup after pre-upgrade failure.
  # Does NOT remove the legacy trusted.gpg.d keyring (additive; intentional).
  local stamp="$1"
  local reason="${2:-pre_upgrade_failure}"
  local bak lists_dst confd
  bak="$(hostpath "${BACKUP_ROOT}/${stamp}")"
  if [[ ! -d "$bak/apt" ]]; then
    log WARN "APT_SOURCES_RESTORE=SKIPPED reason=no_backup stamp=${stamp}"
    return 0
  fi
  log INFO "APT_SOURCES_RESTORE_BEGIN reason=${reason} backup=${bak}"
  if [[ -f "$bak/apt/sources.list" ]]; then
    cp -a "$bak/apt/sources.list" "$(hostpath /etc/apt/sources.list)"
    log INFO "APT_SOURCES_LIST_RESTORED=PASS"
  else
    log WARN "APT_SOURCES_LIST_RESTORED=SKIPPED"
  fi
  lists_dst="$(hostpath /etc/apt/sources.list.d)"
  mkdir -p "$lists_dst"
  if [[ -d "$bak/apt/sources.list.d" ]]; then
    # Replace list.d contents with the pre-mutation snapshot.
    find "$lists_dst" -mindepth 1 -maxdepth 1 -exec rm -rf {} + 2>/dev/null || true
    cp -a "$bak/apt/sources.list.d/." "$lists_dst/" 2>/dev/null || true
    log INFO "APT_SOURCES_LIST_D_RESTORED=PASS"
    log INFO "THIRD_PARTY_SOURCES_RESTORED=PASS"
  else
    log WARN "APT_SOURCES_LIST_D_RESTORED=SKIPPED"
  fi
  confd="$(hostpath /etc/apt/apt.conf.d)"
  rm -f "${confd}/99stellar-offline-upgrade" 2>/dev/null || true
  rm -f "${confd}/98stellar-distupgrade-source-gate" 2>/dev/null || true
  restore_noninteractive_conffile_policy "client_apt_sources_restore" || true
  rm -f "$(hostpath "$DISTUPGRADE_OVERRIDE_CFG")" 2>/dev/null || true
  clear_effective_source_gate_markers "client_apt_sources_restore" || true
  # Prefer restoring update-manager from backup when present.
  if [[ -d "$bak/update-manager" ]]; then
    local um
    um="$(hostpath /etc/update-manager)"
    mkdir -p "$um"
    [[ -f "$bak/update-manager/meta-release" ]] && cp -a "$bak/update-manager/meta-release" "$um/meta-release"
    [[ -f "$bak/update-manager/release-upgrades" ]] && cp -a "$bak/update-manager/release-upgrades" "$um/release-upgrades"
    if [[ -d "$bak/update-manager/release-upgrades.d" ]]; then
      mkdir -p "$um/release-upgrades.d"
      find "$um/release-upgrades.d" -mindepth 1 -maxdepth 1 -exec rm -rf {} + 2>/dev/null || true
      cp -a "$bak/update-manager/release-upgrades.d/." "$um/release-upgrades.d/" 2>/dev/null || true
    else
      rm -f "$um/release-upgrades.d/99-stellar-offline-mirror.cfg" 2>/dev/null || true
    fi
    log INFO "UPDATE_MANAGER_RESTORED=PASS"
  fi
  log INFO "DISTUPGRADE_TEMP_OVERRIDE_REMOVED=PASS"
  log INFO "APT_CONF_STELLAR_REMOVED=PASS"
  log INFO "LEGACY_APT_KEYRING_RETAINED=YES"
  log INFO "LEGACY_APT_KEYRING_RETAIN_POLICY=additive_trusted_gpg_d_on_pre_upgrade_failure"
  log INFO "APT_SOURCES_RESTORE_RESULT=PASS"
  return 0
}

install_legacy_apt_keyring() {
  # Install selective signing key into dedicated trusted.gpg.d keyring (atomic).
  # Destructive confirmation must already have passed; preflight stays read-only.
  local work="$1"
  local src dest dir tmpf fpr installed_fpr
  src="$work/stellar-offline-upgrade.gpg"
  [[ -f "$src" ]] || die "$EC_TRUST" "FAIL_LEGACY_APT_KEYRING_INSTALL: embedded key missing"
  dir="$(hostpath /etc/apt/trusted.gpg.d)"
  dest="$(hostpath "$LEGACY_APT_KEYRING_PATH")"
  mkdir -p "$dir"
  chmod 0755 "$dir"

  fpr=""
  fpr="$(gpg --no-default-keyring --keyring "$src" --with-colons --fingerprint 2>/dev/null \
    | awk -F: '/^fpr:/ {print $10; exit}' || true)"
  fpr="$(printf '%s' "$fpr" | tr '[:lower:]' '[:upper:]')"
  log INFO "LEGACY_APT_KEYRING_PATH=${LEGACY_APT_KEYRING_PATH}"
  log INFO "LEGACY_APT_KEY_FINGERPRINT=${fpr}"
  if [[ -n "$TEST_ROOT" && ( "$PIN_KEY_FINGERPRINT" == "DEADBEEF" || "${DP_OFFLINE_FAKE_MIRROR_TRUST:-}" == "1" ) ]]; then
    log WARN "TEST_ROOT: skipping legacy key fingerprint hard-match"
    log INFO "LEGACY_APT_KEY_FINGERPRINT_MATCH=PASS"
  elif [[ -z "$fpr" || "$fpr" != "$PIN_KEY_FINGERPRINT" ]]; then
    log ERROR "FAIL_LEGACY_APT_KEY_FINGERPRINT_MISMATCH"
    log INFO "LEGACY_APT_KEY_FINGERPRINT_MATCH=FAIL"
    die "$EC_TRUST" "FAIL_LEGACY_APT_KEY_FINGERPRINT_MISMATCH"
  else
    log INFO "LEGACY_APT_KEY_FINGERPRINT_MATCH=PASS"
  fi

  tmpf="${dest}.tmp.$$"
  # Ensure binary keyring form (dearmor if ASCII-armored).
  if grep -q 'BEGIN PGP PUBLIC KEY BLOCK' "$src" 2>/dev/null; then
    gpg --dearmor <"$src" >"$tmpf" || {
      rm -f "$tmpf"
      die "$EC_TRUST" "FAIL_LEGACY_APT_KEYRING_INSTALL: gpg --dearmor failed"
    }
  else
    cp -f "$src" "$tmpf" || {
      rm -f "$tmpf"
      die "$EC_TRUST" "FAIL_LEGACY_APT_KEYRING_INSTALL: copy failed"
    }
  fi
  chmod 0644 "$tmpf"
  mv -f "$tmpf" "$dest" || die "$EC_TRUST" "FAIL_LEGACY_APT_KEYRING_INSTALL: atomic rename failed"
  chown root:root "$dest" 2>/dev/null || true

  installed_fpr=""
  installed_fpr="$(gpg --no-default-keyring --keyring "$dest" --with-colons --fingerprint 2>/dev/null \
    | awk -F: '/^fpr:/ {print $10; exit}' || true)"
  installed_fpr="$(printf '%s' "$installed_fpr" | tr '[:lower:]' '[:upper:]')"
  if [[ -n "$TEST_ROOT" && ( "$PIN_KEY_FINGERPRINT" == "DEADBEEF" || "${DP_OFFLINE_FAKE_MIRROR_TRUST:-}" == "1" ) ]]; then
    log INFO "LEGACY_APT_KEY_INSTALL=PASS"
  elif [[ -z "$installed_fpr" || "$installed_fpr" != "$PIN_KEY_FINGERPRINT" ]]; then
    log ERROR "FAIL_LEGACY_APT_KEYRING_POSTINSTALL_VALIDATION"
    die "$EC_TRUST" "FAIL_LEGACY_APT_KEYRING_POSTINSTALL_VALIDATION"
  else
    log INFO "LEGACY_APT_KEY_INSTALL=PASS"
  fi
  # Also keep a copy under keyrings/ for operators inspecting older paths (optional).
  mkdir -p "$(hostpath /etc/apt/keyrings)"
  cp -f "$dest" "$(hostpath /etc/apt/keyrings/stellar-offline-upgrade.gpg)" 2>/dev/null || true
}

# Alias for older call sites / backups that still name install_keyring.
install_keyring() {
  install_legacy_apt_keyring "$@"
}

write_legacy_compatible_sources() {
  # Args: dest_path suite_list (space-separated)
  # Writes DistUpgrade-compatible deb lines with arch option only.
  # Forbidden in generated lines: signed-by option, trusted option set to yes.
  local dest="$1"
  local suites="$2"
  local repo="${MIRROR_BASE}/hops/${PIN_HOP}/ubuntu"
  local s
  {
    printf '# stellar offline upgrade %s - DistUpgrade-compatible (no signed-by)\n' "$PIN_HOP"
    for s in $suites; do
      printf 'deb [arch=amd64] %s %s %s\n' "$repo" "$s" "$PIN_COMPONENTS"
    done
  } >"${dest}.new"
  if grep -qiE 'signed-by=|trusted[[:space:]]*=[[:space:]]*yes|AllowUnauthenticated|(archive|security|old-releases)\.ubuntu\.com' "${dest}.new"; then
    rm -f "${dest}.new"
    die "$EC_INTERNAL" "refusing to write unsafe/DistUpgrade-incompatible sources"
  fi
  mv -f "${dest}.new" "$dest"
}

apply_local_sources() {
  # Host pre-DRO sources: SOURCE suites only (cross-release guard). No signed-by=.
  local listf confd
  listf="$(hostpath /etc/apt/sources.list)"
  write_legacy_compatible_sources "$listf" "$PIN_SOURCE_SUITES"

  # DistUpgrade target sources (validated separately; DistUpgrade rewrite target form).
  # NOTE: DistUpgrade does NOT read this path at runtime - it rewrites /etc/apt/sources.list
  # via isMirror(ValidMirrors). This file is the expected post-rewrite form + PRE-DRO gate.
  mkdir -p "$(hostpath "$STATE_ROOT")"
  write_legacy_compatible_sources "$(hostpath "$DISTUPGRADE_SOURCES_PATH")" "$PIN_TARGET_SUITES"

  confd="$(hostpath /etc/apt/apt.conf.d)"
  mkdir -p "$confd"
  cat >"${confd}/99stellar-offline-upgrade" <<EOF
Acquire::Languages "none";
Acquire::AllowInsecureRepositories "false";
APT::Get::AllowUnauthenticated "false";
EOF
}

local_selective_mirror_uri() {
  printf '%s/hops/%s/ubuntu' "${MIRROR_BASE%/}" "$PIN_HOP"
}

apply_distupgrade_mirror_override() {
  # Official DistUpgradeConfig override: /etc/update-manager/release-upgrades.d/*.cfg
  # Registers the selective local URI in ValidMirrors (absolute path - join keeps it)
  # and sets AllowThirdParty so internal mirrors are not disabled as "unknown".
  # IMPORTANT: DistUpgradeConfigParser (Bionic/Python 3.5) reads these with the
  # process locale encoding. Under LC_ALL=C that is ASCII - comments/body must
  # be ASCII-only (no em dash, en dash, arrows, smart quotes, NBSP, BOM).
  local mirrors_path cfg_path ov_dir repo
  repo="$(local_selective_mirror_uri)"
  mirrors_path="$(hostpath "$DISTUPGRADE_MIRRORS_FILE")"
  ov_dir="$(hostpath "$DISTUPGRADE_OVERRIDE_DIR")"
  cfg_path="$(hostpath "$DISTUPGRADE_OVERRIDE_CFG")"
  mkdir -p "$(dirname "$mirrors_path")" "$ov_dir" \
    "$(hostpath "$(dirname "$EFFECTIVE_SOURCE_GATE_BIN")")" \
    "$(hostpath "$EFFECTIVE_SOURCE_CAPTURE_DIR")"

  cat >"${mirrors_path}.new" <<EOF
# stellar offline DistUpgrade ValidMirrors overlay (Xenial-to-Bionic)
# Official essentials retained; local selective hop registered as Ubuntu archive mirror.
http://archive.ubuntu.com/ubuntu/
http://security.ubuntu.com/ubuntu/
http://ports.ubuntu.com/ubuntu-ports/
http://old-releases.ubuntu.com/ubuntu/
${repo}
${repo}/
EOF
  mv -f "${mirrors_path}.new" "$mirrors_path"
  chmod 0644 "$mirrors_path"

  cat >"${cfg_path}.new" <<EOF
# Generated by stellar offline Xenial-to-Bionic client.
# DistUpgradeConfig reads release-upgrades.d/*.cfg after DistUpgrade.cfg.xenial.
[Sources]
ValidMirrors=${mirrors_path}
AllowThirdParty=yes
EOF
  mv -f "${cfg_path}.new" "$cfg_path"
  chmod 0644 "$cfg_path"
  assert_ascii_file "$mirrors_path" "FAIL_DISTUPGRADE_CONFIG_NONASCII" \
    || die "$EC_DISTUPGRADE_CONFIG" "FAIL_DISTUPGRADE_CONFIG_NONASCII"
  assert_ascii_file "$cfg_path" "FAIL_DISTUPGRADE_CONFIG_NONASCII" \
    || die "$EC_DISTUPGRADE_CONFIG" "FAIL_DISTUPGRADE_CONFIG_NONASCII"
  log INFO "DISTUPGRADE_VALID_MIRRORS_FILE=${DISTUPGRADE_MIRRORS_FILE}"
  log INFO "DISTUPGRADE_OVERRIDE_CFG=${DISTUPGRADE_OVERRIDE_CFG}"
  log INFO "DISTUPGRADE_LOCAL_MIRROR_REGISTERED=${repo}"
  log INFO "DISTUPGRADE_ALLOW_THIRD_PARTY=yes"
  log INFO "DISTUPGRADE_CONFIG_ASCII_WRITE=PASS"
}

install_effective_source_gate() {
  # Install APT::Update::Pre-Invoke hook in DISARMED state.
  # Enforcement begins only after arm_effective_source_gate() (do-release-upgrade eve).
  local bin_path apt_path repo capture_dir armed_marker passed_marker gate_log evid_root
  repo="$(local_selective_mirror_uri)"
  bin_path="$(hostpath "$EFFECTIVE_SOURCE_GATE_BIN")"
  apt_path="$(hostpath "$EFFECTIVE_SOURCE_GATE_APT")"
  capture_dir="$(hostpath "$EFFECTIVE_SOURCE_CAPTURE_DIR")"
  armed_marker="$(hostpath "$EFFECTIVE_SOURCE_GATE_ARMED_MARKER")"
  passed_marker="$(hostpath "$EFFECTIVE_SOURCE_GATE_PASSED_MARKER")"
  gate_log="$(hostpath "$EFFECTIVE_SOURCE_GATE_LOG")"
  evid_root="$(hostpath "$EFFECTIVE_SOURCE_GATE_EVIDENCE_ROOT")"
  mkdir -p "$(dirname "$bin_path")" "$capture_dir" "$(dirname "$apt_path")" \
    "$(dirname "$gate_log")" "$evid_root"
  # Fresh install is always DISARMED - SOURCE_RELEASE_PREPARATION apt-get update must pass.
  rm -f "$armed_marker" "$passed_marker"

  cat >"${bin_path}.new" <<'GATE'
#!/usr/bin/env python3
from __future__ import print_function
import os, re, sys, time, traceback
from collections import Counter

OFFICIAL_RE = re.compile(
    r'(?:^|://)(?:(?:[a-z]{2}\.)?archive\.ubuntu\.com|security\.ubuntu\.com|'
    r'ports\.ubuntu\.com|old-releases\.ubuntu\.com)(?:[:/]|$)', re.I)

def utc_now():
    return time.strftime('%Y-%m-%dT%H:%M:%SZ', time.gmtime())

def parse_entry(line):
    raw = line.strip()
    if not raw or raw.startswith('#'):
        return None
    if '#' in raw:
        raw = raw[:raw.find('#')].strip()
    pieces, tmp, p_found, space_found = [], '', False, False
    for ch in raw:
        if ch == '[':
            if space_found:
                space_found = False
                p_found = True
                pieces.append(tmp)
                tmp = ch
            else:
                p_found = True
                tmp += ch
        elif ch == ']':
            p_found = False
            tmp += ch
        elif space_found and not ch.isspace():
            space_found = False
            pieces.append(tmp)
            tmp = ch
        elif ch.isspace() and not p_found:
            space_found = True
        else:
            tmp += ch
    if tmp:
        pieces.append(tmp)
    if len(pieces) < 3 or pieces[0] not in ('deb', 'deb-src'):
        return None
    idx = 1
    archs = []
    if pieces[1].startswith('['):
        for opt in pieces[1][1:-1].split():
            if opt.startswith('arch='):
                archs = opt.split('=', 1)[1].split(',')
            elif opt.startswith('signed-by=') or opt.lower() == 'trusted=yes' \
                    or opt.lower().startswith('trusted=yes'):
                return {'forbidden': 'signed-by-or-trusted', 'raw': line.strip()}
            elif '=' in opt and not opt.startswith('trusted='):
                return {'forbidden': opt.split('=', 1)[0], 'raw': line.strip()}
        idx = 2
    if idx + 1 >= len(pieces):
        return None
    return {
        'type': pieces[0], 'uri': pieces[idx].rstrip('/'),
        'dist': pieces[idx + 1], 'comps': pieces[idx + 2:],
        'archs': archs, 'forbidden': '', 'raw': line.strip(),
    }

def read_marker(path):
    data = {}
    if not path or not os.path.isfile(path):
        return data
    try:
        for line in open(path, 'r').read().splitlines():
            line = line.strip()
            if not line or line.startswith('#') or '=' not in line:
                continue
            k, v = line.split('=', 1)
            data[k.strip()] = v.strip()
    except Exception:
        return None
    return data

def append_log(path, lines):
    if not path:
        return
    try:
        d = os.path.dirname(path)
        if d and not os.path.isdir(d):
            os.makedirs(d)
        with open(path, 'a') as fh:
            for ln in lines:
                fh.write(ln if ln.endswith('\n') else (ln + '\n'))
    except Exception:
        pass

def list_source_files(sources_list, sources_list_d):
    files = []
    if sources_list and os.path.isfile(sources_list):
        files.append(sources_list)
    if sources_list_d and os.path.isdir(sources_list_d):
        try:
            names = sorted(os.listdir(sources_list_d))
        except Exception:
            names = []
        for name in names:
            if name.startswith('.'):
                continue
            if not (name.endswith('.list') or name == 'sources.list'):
                continue
            p = os.path.join(sources_list_d, name)
            if os.path.isfile(p):
                files.append(p)
    return files

def read_proc_cmdline(pid):
    try:
        raw = open('/proc/%s/cmdline' % pid, 'rb').read()
        return raw.replace(b'\x00', b' ').decode('utf-8', 'replace').strip()
    except Exception:
        return ''

def next_invocation_dir(evid_root):
    if not evid_root:
        return ''
    try:
        if not os.path.isdir(evid_root):
            os.makedirs(evid_root)
        n = 1
        while True:
            path = os.path.join(evid_root, 'invocation-%d' % n)
            if not os.path.exists(path):
                os.makedirs(path)
                return path
            n += 1
            if n > 10000:
                return ''
    except Exception:
        return ''

def snapshot_sources(inv_dir, source_files, result_env_lines):
    if not inv_dir:
        return
    try:
        for src in source_files:
            base = os.path.basename(src)
            if src.endswith('sources.list') and base == 'sources.list':
                dest = os.path.join(inv_dir, 'sources.list')
            else:
                ddir = os.path.join(inv_dir, 'sources.list.d')
                if not os.path.isdir(ddir):
                    os.makedirs(ddir)
                dest = os.path.join(ddir, base)
            try:
                open(dest, 'wb').write(open(src, 'rb').read())
            except Exception:
                pass
        open(os.path.join(inv_dir, 'result.env'), 'w').write(
            '\n'.join(result_env_lines) + '\n')
    except Exception:
        pass

def main():
    log_path = os.environ.get(
        'STELLAR_GATE_LOG', '/var/log/aella/distupgrade_effective_source_gate.log')
    armed_path = os.environ.get('STELLAR_GATE_ARMED_MARKER', '')
    passed_path = os.environ.get('STELLAR_GATE_PASSED_MARKER', '')
    evid_root = os.environ.get('STELLAR_GATE_EVIDENCE_ROOT', '')
    state_file = os.environ.get('STELLAR_STATE_FILE', '')
    inv_marker = os.environ.get('STELLAR_RELEASE_UPGRADE_INVOCATION_MARKER', '')
    pkg_marker = os.environ.get('STELLAR_PACKAGE_TRANSITION_MARKER', '')
    stage_file = os.environ.get('STELLAR_GATE_STAGE_FILE', '')
    sources = os.environ.get('STELLAR_SOURCES_LIST', '/etc/apt/sources.list')
    sources_d = os.environ.get('STELLAR_SOURCES_LIST_D', '/etc/apt/sources.list.d')
    capture_dir = os.environ.get('STELLAR_EFFECTIVE_CAPTURE_DIR', '')
    expected_uri = os.environ.get('STELLAR_EXPECTED_MIRROR_URI', '').rstrip('/')
    to_series = os.environ.get('STELLAR_TARGET_CODENAME', 'bionic')
    from_series = os.environ.get('STELLAR_SOURCE_CODENAME', 'xenial')
    components = os.environ.get('STELLAR_COMPONENTS', 'main universe').split()
    hop = os.environ.get('STELLAR_EXPECTED_HOP', '')
    run_id = os.environ.get('STELLAR_RUN_ID', '')
    expected = [to_series, to_series + '-updates', to_series + '-security',
                to_series + '-backports']

    out = []
    def emit(k, v):
        line = '%s=%s' % (k, v)
        out.append(line)
        sys.stdout.write(line + '\n')

    ppid = os.getppid()
    cur_state = ''
    if state_file and os.path.isfile(state_file):
        try:
            cur_state = open(state_file).read().strip().splitlines()[0]
        except Exception:
            cur_state = ''
    cur_stage = ''
    if stage_file and os.path.isfile(stage_file):
        try:
            cur_stage = open(stage_file).read().strip().splitlines()[0]
        except Exception:
            cur_stage = ''
    inv_flag = 'unknown'
    if inv_marker and os.path.isfile(inv_marker):
        try:
            inv_flag = open(inv_marker).read().strip() or 'true'
        except Exception:
            inv_flag = 'true'
    pkg_flag = 'unknown'
    if pkg_marker and os.path.isfile(pkg_marker):
        try:
            pkg_flag = open(pkg_marker).read().strip() or 'true'
        except Exception:
            pkg_flag = 'true'

    marker = read_marker(armed_path)
    if marker is None:
        emit('DISTUPGRADE_EFFECTIVE_SOURCE_GATE_STATE', 'FAILED')
        emit('DISTUPGRADE_EFFECTIVE_SOURCE_GATE_ACTION', 'DENY')
        emit('DISTUPGRADE_EFFECTIVE_SOURCE_GATE_REASON', 'ARM_MARKER_UNREADABLE')
        emit('DISTUPGRADE_EFFECTIVE_SOURCE_GATE_RESULT', 'FAIL')
        emit('error', 'FAIL_DISTUPGRADE_EFFECTIVE_SOURCE_GATE_CONFIG')
        rc = 10
        append_log(log_path, [
            '--- %s pid=%s ppid=%s ---' % (utc_now(), os.getpid(), ppid),
            'ppid_cmdline=%s' % read_proc_cmdline(ppid),
            'run_id=%s' % run_id,
            'state=%s stage=%s invocation=%s transition=%s' % (
                cur_state, cur_stage, inv_flag, pkg_flag),
        ] + out + ['exit_code=%s' % rc, ''])
        return rc

    if not marker:
        emit('DISTUPGRADE_EFFECTIVE_SOURCE_GATE_STATE', 'DISARMED')
        emit('DISTUPGRADE_EFFECTIVE_SOURCE_GATE_ACTION', 'ALLOW')
        emit('DISTUPGRADE_EFFECTIVE_SOURCE_GATE_REASON', 'NOT_ARMED')
        emit('DISTUPGRADE_EFFECTIVE_SOURCE_GATE_RESULT', 'PASS')
        rc = 0
        append_log(log_path, [
            '--- %s pid=%s ppid=%s ---' % (utc_now(), os.getpid(), ppid),
            'ppid_cmdline=%s' % read_proc_cmdline(ppid),
            'run_id=%s' % run_id,
            'armed=NO',
            'state=%s stage=%s invocation=%s transition=%s' % (
                cur_state, cur_stage, inv_flag, pkg_flag),
        ] + out + ['exit_code=%s' % rc, ''])
        return rc

    # Prefer arm-marker values over env (root-owned lifecycle contract).
    expected_uri = marker.get('EXPECTED_MIRROR_URI', expected_uri).rstrip('/')
    to_series = marker.get('EXPECTED_TARGET_CODENAME', to_series)
    from_series = marker.get('EXPECTED_SOURCE_CODENAME', from_series)
    hop = marker.get('EXPECTED_HOP', hop)
    run_id = marker.get('RUN_ID', run_id)
    expected = [to_series, to_series + '-updates', to_series + '-security',
                to_series + '-backports']
    if not expected_uri or not to_series or not from_series:
        emit('DISTUPGRADE_EFFECTIVE_SOURCE_GATE_STATE', 'FAILED')
        emit('DISTUPGRADE_EFFECTIVE_SOURCE_GATE_ACTION', 'DENY')
        emit('DISTUPGRADE_EFFECTIVE_SOURCE_GATE_REASON', 'ARM_MARKER_INCOMPLETE')
        emit('DISTUPGRADE_EFFECTIVE_SOURCE_GATE_RESULT', 'FAIL')
        emit('error', 'FAIL_DISTUPGRADE_EFFECTIVE_SOURCE_GATE_CONFIG')
        rc = 10
        append_log(log_path, [
            '--- %s pid=%s ppid=%s ---' % (utc_now(), os.getpid(), ppid),
            'ppid_cmdline=%s' % read_proc_cmdline(ppid),
            'run_id=%s' % run_id,
            'armed=YES',
        ] + out + ['exit_code=%s' % rc, ''])
        return rc

    source_files = list_source_files(sources, sources_d)
    emit('DISTUPGRADE_EFFECTIVE_SOURCE_FILE', ','.join(source_files) or sources)
    enabled = []
    official = 0
    active_lines = []
    try:
        for path in source_files:
            try:
                text = open(path, 'rb').read().decode('utf-8-sig')
            except Exception as exc:
                emit('DISTUPGRADE_EFFECTIVE_SOURCE_CAPTURE', 'FAIL')
                emit('DISTUPGRADE_EFFECTIVE_SOURCE_GATE_STATE', 'FAILED')
                emit('DISTUPGRADE_EFFECTIVE_SOURCE_GATE_ACTION', 'DENY')
                emit('DISTUPGRADE_EFFECTIVE_SOURCE_GATE_REASON', 'SOURCE_READ_ERROR')
                emit('DISTUPGRADE_EFFECTIVE_SOURCE_GATE_RESULT', 'FAIL')
                emit('error', 'FAIL_DISTUPGRADE_EFFECTIVE_SOURCE_GATE_INTERNAL')
                emit('detail', '%s: %s' % (path, exc))
                rc = 11
                append_log(log_path, [
                    '--- %s pid=%s ppid=%s ---' % (utc_now(), os.getpid(), ppid),
                    'ppid_cmdline=%s' % read_proc_cmdline(ppid),
                    'run_id=%s' % run_id,
                    'armed=YES',
                ] + out + ['exit_code=%s' % rc, ''])
                return rc
            if capture_dir:
                try:
                    if not os.path.isdir(capture_dir):
                        os.makedirs(capture_dir)
                    open(os.path.join(
                        capture_dir, 'sources.list.capture'), 'w').write(text)
                except Exception:
                    pass
            for line in text.splitlines():
                s = line.strip()
                if not s or s.startswith('#'):
                    continue
                if OFFICIAL_RE.search(s):
                    official += 1
                ent = parse_entry(s)
                if not ent:
                    continue
                if ent.get('forbidden'):
                    emit('DISTUPGRADE_EFFECTIVE_SOURCE_CAPTURE', 'FAIL')
                    emit('DISTUPGRADE_EFFECTIVE_SOURCE_GATE_STATE',
                         'ENFORCING_TARGET_SOURCES')
                    emit('DISTUPGRADE_EFFECTIVE_SOURCE_GATE_ACTION', 'DENY')
                    emit('DISTUPGRADE_EFFECTIVE_SOURCE_GATE_REASON',
                         'FORBIDDEN_SOURCE_OPTION')
                    emit('DISTUPGRADE_EFFECTIVE_SOURCE_GATE_RESULT', 'FAIL')
                    emit('error', 'FAIL_TRUSTED_YES_FORBIDDEN'
                         if 'trusted' in ent['forbidden']
                         else 'FAIL_SIGNED_BY_PRESENT_IN_DISTUPGRADE_SOURCE')
                    rc = 3
                    inv_dir = next_invocation_dir(evid_root)
                    snapshot_sources(inv_dir, source_files, out)
                    append_log(log_path, [
                        '--- %s pid=%s ppid=%s ---' % (utc_now(), os.getpid(), ppid),
                        'ppid_cmdline=%s' % read_proc_cmdline(ppid),
                        'run_id=%s' % run_id,
                        'armed=YES',
                        'active_deb_lines:',
                    ] + active_lines + out + ['exit_code=%s' % rc, ''])
                    return rc
                if ent['type'] != 'deb':
                    continue
                enabled.append(ent)
                active_lines.append(ent.get('raw', s))
    except Exception as exc:
        emit('DISTUPGRADE_EFFECTIVE_SOURCE_GATE_STATE', 'FAILED')
        emit('DISTUPGRADE_EFFECTIVE_SOURCE_GATE_ACTION', 'DENY')
        emit('DISTUPGRADE_EFFECTIVE_SOURCE_GATE_REASON', 'INTERNAL_EXCEPTION')
        emit('DISTUPGRADE_EFFECTIVE_SOURCE_GATE_RESULT', 'FAIL')
        emit('error', 'FAIL_DISTUPGRADE_EFFECTIVE_SOURCE_GATE_INTERNAL')
        emit('detail', str(exc))
        rc = 11
        append_log(log_path, [
            '--- %s pid=%s ppid=%s ---' % (utc_now(), os.getpid(), ppid),
            'traceback=%s' % traceback.format_exc().replace('\n', ' | '),
        ] + out + ['exit_code=%s' % rc, ''])
        return rc

    dists = [e['dist'] for e in enabled]
    has_tgt = any(d == to_series or d.startswith(to_series + '-') for d in dists)
    has_src = any(d == from_series or d.startswith(from_series + '-') for d in dists)
    src_count = sum(1 for d in dists
                    if d == from_series or d.startswith(from_series + '-'))
    tgt_count = sum(1 for d in dists
                    if d == to_series or d.startswith(to_series + '-'))
    emit('DISTUPGRADE_EFFECTIVE_SOURCE_GATE_SOURCE_SUITE_COUNT', str(src_count))
    emit('DISTUPGRADE_EFFECTIVE_SOURCE_GATE_TARGET_SUITE_COUNT', str(tgt_count))
    emit('DISTUPGRADE_EFFECTIVE_SOURCE_COUNT', str(len(enabled)))
    emit('DISTUPGRADE_OFFICIAL_ARCHIVE_REFERENCE_COUNT', str(official))
    dup = sum(c - 1 for c in Counter(dists).values() if c > 1)
    emit('DISTUPGRADE_EFFECTIVE_SOURCE_DUPLICATE_COUNT', str(dup))

    # Armed but target rewrite not visible yet → deterministic defer.
    if has_src and not has_tgt:
        if official:
            emit('DISTUPGRADE_EFFECTIVE_SOURCE_GATE_STATE',
                 'ARMED_WAITING_FOR_TARGET_REWRITE')
            emit('DISTUPGRADE_EFFECTIVE_SOURCE_GATE_ACTION', 'DENY')
            emit('DISTUPGRADE_EFFECTIVE_SOURCE_GATE_REASON',
                 'OFFICIAL_URL_BEFORE_TARGET_REWRITE')
            emit('DISTUPGRADE_EFFECTIVE_SOURCE_CAPTURE', 'FAIL')
            emit('DISTUPGRADE_EFFECTIVE_SOURCE_LOCAL_MIRROR_ONLY', 'FAIL')
            emit('DISTUPGRADE_EFFECTIVE_SOURCE_GATE_RESULT', 'FAIL')
            emit('error', 'FAIL_DISTUPGRADE_EFFECTIVE_SOURCE_OFFLINE_ESCAPE')
            rc = 4
        elif any(e['uri'] != expected_uri for e in enabled):
            emit('DISTUPGRADE_EFFECTIVE_SOURCE_GATE_STATE',
                 'ARMED_WAITING_FOR_TARGET_REWRITE')
            emit('DISTUPGRADE_EFFECTIVE_SOURCE_GATE_ACTION', 'DENY')
            emit('DISTUPGRADE_EFFECTIVE_SOURCE_GATE_REASON',
                 'UNEXPECTED_URI_BEFORE_TARGET_REWRITE')
            emit('DISTUPGRADE_EFFECTIVE_SOURCE_CAPTURE', 'FAIL')
            emit('DISTUPGRADE_EFFECTIVE_SOURCE_LOCAL_MIRROR_ONLY', 'FAIL')
            emit('DISTUPGRADE_EFFECTIVE_SOURCE_GATE_RESULT', 'FAIL')
            emit('error', 'FAIL_DISTUPGRADE_EFFECTIVE_SOURCE_OFFLINE_ESCAPE')
            rc = 4
        else:
            emit('DISTUPGRADE_EFFECTIVE_SOURCE_GATE_STATE',
                 'ARMED_WAITING_FOR_TARGET_REWRITE')
            emit('DISTUPGRADE_EFFECTIVE_SOURCE_GATE_ACTION', 'DEFER')
            emit('DISTUPGRADE_EFFECTIVE_SOURCE_GATE_REASON',
                 'TARGET_REWRITE_NOT_YET_VISIBLE')
            emit('DISTUPGRADE_EFFECTIVE_SOURCE_GATE_RESULT', 'PASS')
            rc = 0
        inv_dir = next_invocation_dir(evid_root)
        snapshot_sources(inv_dir, source_files, out)
        append_log(log_path, [
            '--- %s pid=%s ppid=%s ---' % (utc_now(), os.getpid(), ppid),
            'ppid_cmdline=%s' % read_proc_cmdline(ppid),
            'run_id=%s hop=%s' % (run_id, hop),
            'armed=YES',
            'state=%s stage=%s invocation=%s transition=%s' % (
                cur_state, cur_stage, inv_flag, pkg_flag),
            'inspected_files=%s' % ','.join(source_files),
            'active_deb_lines:',
        ] + active_lines + out + ['exit_code=%s' % rc, ''])
        return rc

    # Target suites visible → strict enforce.
    emit('DISTUPGRADE_EFFECTIVE_SOURCE_GATE_STATE', 'ENFORCING_TARGET_SOURCES')
    if official:
        emit('DISTUPGRADE_EFFECTIVE_SOURCE_CAPTURE', 'FAIL')
        emit('DISTUPGRADE_EFFECTIVE_SOURCE_LOCAL_MIRROR_ONLY', 'FAIL')
        emit('DISTUPGRADE_EFFECTIVE_SOURCE_GATE_ACTION', 'DENY')
        emit('DISTUPGRADE_EFFECTIVE_SOURCE_GATE_REASON', 'OFFICIAL_ARCHIVE_REFERENCE')
        emit('DISTUPGRADE_EFFECTIVE_SOURCE_GATE_RESULT', 'FAIL')
        emit('error', 'FAIL_DISTUPGRADE_EFFECTIVE_SOURCE_OFFLINE_ESCAPE')
        rc = 4
        inv_dir = next_invocation_dir(evid_root)
        snapshot_sources(inv_dir, source_files, out)
        append_log(log_path, [
            '--- %s pid=%s ppid=%s ---' % (utc_now(), os.getpid(), ppid),
            'ppid_cmdline=%s' % read_proc_cmdline(ppid),
            'run_id=%s' % run_id,
            'armed=YES',
            'inspected_files=%s' % ','.join(source_files),
            'active_deb_lines:',
        ] + active_lines + out + ['exit_code=%s' % rc, ''])
        return rc

    if dup:
        emit('DISTUPGRADE_EFFECTIVE_SOURCE_CAPTURE', 'FAIL')
        emit('DISTUPGRADE_EFFECTIVE_SOURCE_GATE_ACTION', 'DENY')
        emit('DISTUPGRADE_EFFECTIVE_SOURCE_GATE_REASON', 'DUPLICATE_SUITE')
        emit('DISTUPGRADE_EFFECTIVE_SOURCE_GATE_RESULT', 'FAIL')
        emit('error', 'FAIL_DISTUPGRADE_EFFECTIVE_SOURCE_DUPLICATE')
        rc = 5
        inv_dir = next_invocation_dir(evid_root)
        snapshot_sources(inv_dir, source_files, out)
        append_log(log_path, [
            '--- %s pid=%s ppid=%s ---' % (utc_now(), os.getpid(), ppid),
            'ppid_cmdline=%s' % read_proc_cmdline(ppid),
            'run_id=%s' % run_id,
            'armed=YES',
            'active_deb_lines:',
        ] + active_lines + out + ['exit_code=%s' % rc, ''])
        return rc

    missing = [s for s in expected if s not in dists]
    if missing or len(enabled) != 4:
        emit('DISTUPGRADE_EFFECTIVE_SOURCE_CAPTURE', 'FAIL')
        emit('DISTUPGRADE_EFFECTIVE_SOURCE_GATE_ACTION', 'DENY')
        if missing:
            emit('DISTUPGRADE_EFFECTIVE_SOURCE_GATE_REASON',
                 'MISSING_POCKET:' + ','.join(missing))
            emit('error', 'FAIL_DISTUPGRADE_EFFECTIVE_SOURCE_MISSING_POCKET')
            rc = 7
        else:
            emit('DISTUPGRADE_EFFECTIVE_SOURCE_GATE_REASON', 'COUNT_MISMATCH')
            emit('error', 'FAIL_DISTUPGRADE_EFFECTIVE_SOURCE_COUNT_MISMATCH')
            rc = 6
        emit('DISTUPGRADE_EFFECTIVE_SOURCE_GATE_RESULT', 'FAIL')
        inv_dir = next_invocation_dir(evid_root)
        snapshot_sources(inv_dir, source_files, out)
        append_log(log_path, [
            '--- %s pid=%s ppid=%s ---' % (utc_now(), os.getpid(), ppid),
            'ppid_cmdline=%s' % read_proc_cmdline(ppid),
            'run_id=%s' % run_id,
            'armed=YES',
            'active_deb_lines:',
        ] + active_lines + out + ['exit_code=%s' % rc, ''])
        return rc

    all_ok = True
    bad_uri = False
    for suite in expected:
        key = 'DISTUPGRADE_EFFECTIVE_SOURCE_%s' % suite.replace('-', '_')
        matches = [e for e in enabled if e['dist'] == suite]
        ok = (len(matches) == 1
              and matches[0]['uri'] == expected_uri
              and all(c in matches[0]['comps'] for c in components)
              and (not matches[0]['archs'] or 'amd64' in matches[0]['archs']))
        emit(key, 'PASS' if ok else 'FAIL')
        if not ok:
            all_ok = False
            if matches and matches[0]['uri'] != expected_uri:
                bad_uri = True
    if not all_ok:
        emit('DISTUPGRADE_EFFECTIVE_SOURCE_CAPTURE', 'FAIL')
        emit('DISTUPGRADE_EFFECTIVE_SOURCE_GATE_ACTION', 'DENY')
        emit('DISTUPGRADE_EFFECTIVE_SOURCE_GATE_REASON', 'SUITE_VALIDATION_FAIL')
        emit('DISTUPGRADE_EFFECTIVE_SOURCE_GATE_RESULT', 'FAIL')
        emit('error', 'FAIL_DISTUPGRADE_EFFECTIVE_SOURCE_OFFLINE_ESCAPE' if bad_uri
             else 'FAIL_DISTUPGRADE_EFFECTIVE_SOURCE_COUNT_MISMATCH')
        rc = 4 if bad_uri else 6
        inv_dir = next_invocation_dir(evid_root)
        snapshot_sources(inv_dir, source_files, out)
        append_log(log_path, [
            '--- %s pid=%s ppid=%s ---' % (utc_now(), os.getpid(), ppid),
            'ppid_cmdline=%s' % read_proc_cmdline(ppid),
            'run_id=%s' % run_id,
            'armed=YES',
            'active_deb_lines:',
        ] + active_lines + out + ['exit_code=%s' % rc, ''])
        return rc

    emit('DISTUPGRADE_EFFECTIVE_SOURCE_CAPTURE', 'PASS')
    emit('DISTUPGRADE_EFFECTIVE_SOURCE_LOCAL_MIRROR_ONLY', 'PASS')
    emit('DISTUPGRADE_EFFECTIVE_SOURCE_GATE_ACTION', 'ALLOW')
    emit('DISTUPGRADE_EFFECTIVE_SOURCE_GATE_REASON', 'TARGET_SOURCES_VALID')
    emit('DISTUPGRADE_EFFECTIVE_SOURCE_GATE_RESULT', 'PASS')
    emit('DISTUPGRADE_EFFECTIVE_SOURCE_PHASE', 'TARGET_POST_REWRITE')
    if passed_path:
        try:
            d = os.path.dirname(passed_path)
            if d and not os.path.isdir(d):
                os.makedirs(d)
            body = [
                'GATE_SCHEMA_VERSION=1',
                'EXPECTED_SOURCE_CODENAME=%s' % from_series,
                'EXPECTED_TARGET_CODENAME=%s' % to_series,
                'EXPECTED_MIRROR_URI=%s' % expected_uri,
                'EXPECTED_HOP=%s' % hop,
                'PASSED_AT=%s' % utc_now(),
                'RUN_ID=%s' % run_id,
                'DISTUPGRADE_EFFECTIVE_SOURCE_COUNT=4',
            ]
            open(passed_path + '.new', 'w').write('\n'.join(body) + '\n')
            os.chmod(passed_path + '.new', 0o600)
            os.rename(passed_path + '.new', passed_path)
        except Exception:
            pass
    rc = 0
    inv_dir = next_invocation_dir(evid_root)
    snapshot_sources(inv_dir, source_files, out)
    append_log(log_path, [
        '--- %s pid=%s ppid=%s ---' % (utc_now(), os.getpid(), ppid),
        'ppid_cmdline=%s' % read_proc_cmdline(ppid),
        'run_id=%s hop=%s' % (run_id, hop),
        'armed=YES',
        'state=%s stage=%s invocation=%s transition=%s' % (
            cur_state, cur_stage, inv_flag, pkg_flag),
        'inspected_files=%s' % ','.join(source_files),
        'active_deb_lines:',
    ] + active_lines + out + ['exit_code=%s' % rc, ''])
    return rc

if __name__ == '__main__':
    try:
        sys.exit(main())
    except Exception:
        try:
            log_path = os.environ.get(
                'STELLAR_GATE_LOG',
                '/var/log/aella/distupgrade_effective_source_gate.log')
            append_log(log_path, [
                '--- %s GATE_INTERNAL ---' % utc_now(),
                'traceback=%s' % traceback.format_exc().replace('\n', ' | '),
                'error=FAIL_DISTUPGRADE_EFFECTIVE_SOURCE_GATE_INTERNAL',
                'exit_code=11',
                '',
            ])
            sys.stdout.write(
                'DISTUPGRADE_EFFECTIVE_SOURCE_GATE_RESULT=FAIL\n')
            sys.stdout.write(
                'error=FAIL_DISTUPGRADE_EFFECTIVE_SOURCE_GATE_INTERNAL\n')
        except Exception:
            pass
        sys.exit(11)
GATE
  # Inject runtime constants via wrapper env file next to the gate.
  cat >"${bin_path}.env" <<EOF
STELLAR_EXPECTED_MIRROR_URI=${repo}
STELLAR_TARGET_CODENAME=${PIN_TARGET_CODENAME}
STELLAR_SOURCE_CODENAME=${PIN_SOURCE_CODENAME}
STELLAR_COMPONENTS=${PIN_COMPONENTS}
STELLAR_EXPECTED_HOP=${PIN_HOP}
STELLAR_RUN_ID=${COMMIT_STAMP:-}
STELLAR_SOURCES_LIST=/etc/apt/sources.list
STELLAR_SOURCES_LIST_D=/etc/apt/sources.list.d
STELLAR_EFFECTIVE_CAPTURE_DIR=${capture_dir}
STELLAR_GATE_ARMED_MARKER=${armed_marker}
STELLAR_GATE_PASSED_MARKER=${passed_marker}
STELLAR_GATE_LOG=${gate_log}
STELLAR_GATE_EVIDENCE_ROOT=${evid_root}
STELLAR_STATE_FILE=$(hostpath "$STATE_FILE")
STELLAR_RELEASE_UPGRADE_INVOCATION_MARKER=$(hostpath "${STATE_ROOT}/release_upgrade_invocation_started")
STELLAR_PACKAGE_TRANSITION_MARKER=$(hostpath "${STATE_ROOT}/release_upgrade_package_transition_started")
STELLAR_GATE_STAGE_FILE=$(hostpath "${STATE_ROOT}/runner_stage")
EOF
  # Resilient wrapper: never use nounset; always persist stderr/rc for APT Pre-Invoke.
  cat >"${bin_path}.wrap" <<EOF
#!/bin/bash
# stellar effective-source gate wrapper (Bash 4.3+ / Xenial)
GATE_BIN="${bin_path}"
GATE_ENV="${bin_path}.env"
GATE_LOG="${gate_log}"
mkdir -p "\$(dirname "\$GATE_LOG")" 2>/dev/null || true
{
  echo "=== wrap_start \$(date -u '+%Y-%m-%dT%H:%M:%SZ') pid=\$\$ ppid=\$PPID ==="
  if [[ -r /proc/\$PPID/cmdline ]]; then
    echo -n "ppid_cmdline="
    tr '\\0' ' ' </proc/\$PPID/cmdline
    echo
  fi
} >>"\$GATE_LOG" 2>/dev/null || true
if [[ ! -f "\$GATE_ENV" ]]; then
  echo "error=FAIL_DISTUPGRADE_EFFECTIVE_SOURCE_GATE_CONFIG detail=missing_env" >>"\$GATE_LOG" 2>/dev/null || true
  echo "DISTUPGRADE_EFFECTIVE_SOURCE_GATE_REASON=MISSING_ENV" >>"\$GATE_LOG" 2>/dev/null || true
  exit 10
fi
set -a
# shellcheck disable=SC1090
source "\$GATE_ENV" >>"\$GATE_LOG" 2>&1 || {
  echo "error=FAIL_DISTUPGRADE_EFFECTIVE_SOURCE_GATE_CONFIG detail=source_env_failed" >>"\$GATE_LOG" 2>/dev/null || true
  exit 10
}
set +a
if [[ ! -x /usr/bin/python3 ]]; then
  echo "error=FAIL_DISTUPGRADE_EFFECTIVE_SOURCE_GATE_INTERNAL detail=python3_missing" >>"\$GATE_LOG" 2>/dev/null || true
  exit 11
fi
if [[ ! -f "\$GATE_BIN" ]]; then
  echo "error=FAIL_DISTUPGRADE_EFFECTIVE_SOURCE_GATE_CONFIG detail=gate_bin_missing" >>"\$GATE_LOG" 2>/dev/null || true
  exit 10
fi
# Keep gate key=value on stdout for operators; stderr + wrap meta go to persistent log.
# Python gate also appends a full structured record to GATE_LOG.
/usr/bin/python3 "\$GATE_BIN" "\$@" 2>>"\$GATE_LOG"
rc=\$?
echo "wrap_exit=\$rc" >>"\$GATE_LOG" 2>/dev/null || true
exit "\$rc"
EOF
  mv -f "${bin_path}.new" "$bin_path"
  chmod 0755 "$bin_path" "${bin_path}.wrap"
  chmod 0644 "${bin_path}.env"

  # Activate APT hook only after executable/env/wrapper are in place.
  if [[ ! -x "$bin_path" || ! -x "${bin_path}.wrap" || ! -f "${bin_path}.env" ]]; then
    rm -f "${apt_path}.new" 2>/dev/null || true
    log ERROR "SOURCE_GATE_INSTALL=FAIL"
    log ERROR "SOURCE_GATE_REJECT_REASON=BINARIES_NOT_READY_BEFORE_HOOK"
    die "$EC_INTERNAL" "FAIL_SOURCE_GATE_INSTALL_ORDER"
  fi
  cat >"${apt_path}.new" <<EOF
// stellar offline: effective-source gate (installed DISARMED; armed before DRO)
APT::Update::Pre-Invoke { "${bin_path}.wrap"; };
EOF
  mv -f "${apt_path}.new" "$apt_path"
  chmod 0644 "$apt_path"
  log INFO "SOURCE_GATE_EXECUTABLE_INSTALLED=YES"
  log INFO "SOURCE_GATE_ENV_INSTALLED=YES"
  log INFO "SOURCE_GATE_WRAPPER_INSTALLED=YES"
  log INFO "SOURCE_GATE_APT_HOOK_INSTALLED=YES"
  log INFO "SOURCE_GATE_INSTALL=PASS"
  log INFO "DISTUPGRADE_EFFECTIVE_SOURCE_GATE=${EFFECTIVE_SOURCE_GATE_BIN}"
  log INFO "DISTUPGRADE_EFFECTIVE_SOURCE_GATE_APT=${EFFECTIVE_SOURCE_GATE_APT}"
  log INFO "DISTUPGRADE_EFFECTIVE_SOURCE_GATE_STATE=INSTALLED_DISARMED"
  log INFO "DISTUPGRADE_EFFECTIVE_SOURCE_GATE_ARMED=NO"
}

remove_distupgrade_temp_overrides() {
  # Remove temporary DistUpgrade ValidMirrors override + effective-source gate.
  local cfg aptg
  cfg="$(hostpath "$DISTUPGRADE_OVERRIDE_CFG")"
  aptg="$(hostpath "$EFFECTIVE_SOURCE_GATE_APT")"
  rm -f "$cfg" "$aptg" 2>/dev/null || true
  clear_effective_source_gate_markers "temp_override_removed" || true
  log INFO "DISTUPGRADE_TEMP_OVERRIDE_REMOVED=PASS"
}

clear_effective_source_gate_markers() {
  # Move arm/passed markers into evidence (or delete) during rollback.
  local reason="${1:-rollback}"
  local armed passed evid
  armed="$(hostpath "${EFFECTIVE_SOURCE_GATE_ARMED_MARKER:-${STATE_ROOT}/effective-source-gate.armed}")"
  passed="$(hostpath "${EFFECTIVE_SOURCE_GATE_PASSED_MARKER:-${STATE_ROOT}/effective-source-gate.passed}")"
  evid="$(hostpath "${EFFECTIVE_SOURCE_GATE_EVIDENCE_ROOT:-${STATE_ROOT}/evidence/effective-source-gate}")/clear-$(date -u '+%Y%m%dT%H%M%SZ')-${reason}"
  if [[ -f "$armed" || -f "$passed" ]]; then
    mkdir -p "$evid" 2>/dev/null || true
    [[ -f "$armed" ]] && mv -f "$armed" "$evid/" 2>/dev/null || rm -f "$armed" 2>/dev/null || true
    [[ -f "$passed" ]] && mv -f "$passed" "$evid/" 2>/dev/null || rm -f "$passed" 2>/dev/null || true
    log INFO "DISTUPGRADE_EFFECTIVE_SOURCE_GATE_MARKERS_CLEARED=YES reason=${reason}"
  fi
  rm -f "$armed" "$passed" 2>/dev/null || true
}

validate_distupgrade_sources_file() {
  # Parse sources with Xenial DistUpgrade SourceEntry rules (embedded python).
  # UTF-8 decode is explicit (never locale/ASCII). Decode failure ≠ source invalid.
  local sources_file="$1"
  local expected_suites="$2"
  local py_out py_rc err_token err_file
  LAST_DISTUPGRADE_SOURCE_ERROR=""
  err_file="$(hostpath "${STATE_ROOT}/last-distupgrade-source-error.txt")"
  mkdir -p "$(hostpath "$STATE_ROOT")"
  rm -f "$err_file"
  [[ -f "$sources_file" ]] || {
    LAST_DISTUPGRADE_SOURCE_ERROR="FAIL_DISTUPGRADE_SOURCE_INVALID"
    printf '%s\n' "$LAST_DISTUPGRADE_SOURCE_ERROR" >"$err_file"
    log ERROR "FAIL_DISTUPGRADE_SOURCE_INVALID: missing ${sources_file}"
    return 1
  }
  if grep -q 'signed-by=' "$sources_file"; then
    LAST_DISTUPGRADE_SOURCE_ERROR="FAIL_SIGNED_BY_PRESENT_IN_DISTUPGRADE_SOURCE"
    printf '%s\n' "$LAST_DISTUPGRADE_SOURCE_ERROR" >"$err_file"
    log ERROR "FAIL_SIGNED_BY_PRESENT_IN_DISTUPGRADE_SOURCE"
    return 2
  fi
  if grep -qiE 'trusted[[:space:]]*=[[:space:]]*yes' "$sources_file"; then
    LAST_DISTUPGRADE_SOURCE_ERROR="FAIL_TRUSTED_YES_FORBIDDEN"
    printf '%s\n' "$LAST_DISTUPGRADE_SOURCE_ERROR" >"$err_file"
    log ERROR "FAIL_TRUSTED_YES_FORBIDDEN"
    return 4
  fi
  if grep -qiE 'AllowUnauthenticated[[:space:]]*=[[:space:]]*true' "$sources_file"; then
    LAST_DISTUPGRADE_SOURCE_ERROR="FAIL_ALLOW_UNAUTHENTICATED_FORBIDDEN"
    printf '%s\n' "$LAST_DISTUPGRADE_SOURCE_ERROR" >"$err_file"
    log ERROR "FAIL_ALLOW_UNAUTHENTICATED_FORBIDDEN"
    return 4
  fi
  set +e
  py_out="$(
    EXPECTED_SUITES="$expected_suites" EXPECTED_COMPONENTS="$PIN_COMPONENTS" \
    SOURCES_FILE="$sources_file" python3 - <<'PY'
from __future__ import print_function
import os
import sys
from collections import OrderedDict

def distupgrade_source_entry_valid(line):
    result = OrderedDict([
        ('invalid', False), ('dist', ''), ('comps', []), ('rejected_options', []),
    ])
    raw = line.strip()
    if not raw or raw.startswith('#'):
        result['invalid'] = True
        return result
    comment_i = raw.find('#')
    if comment_i > 0:
        raw = raw[:comment_i]
    pieces, tmp, p_found, space_found = [], '', False, False
    for ch in raw.strip():
        if ch == '[':
            if space_found:
                space_found = False
                p_found = True
                pieces.append(tmp)
                tmp = ch
            else:
                p_found = True
                tmp += ch
        elif ch == ']':
            p_found = False
            tmp += ch
        elif space_found and not ch.isspace():
            space_found = False
            pieces.append(tmp)
            tmp = ch
        elif ch.isspace() and not p_found:
            space_found = True
        else:
            tmp += ch
    if tmp:
        pieces.append(tmp)
    if len(pieces) < 3 or pieces[0].strip() not in ('deb', 'deb-src'):
        result['invalid'] = True
        return result
    idx = 1
    if pieces[1].strip().startswith('['):
        options = pieces[1].strip()[1:-1].split()
        idx = 2
        for option in options:
            if '=' not in option:
                result['invalid'] = True
                result['rejected_options'].append(option)
                continue
            key, _value = option.split('=', 1)
            if key not in ('arch', 'trusted'):
                result['invalid'] = True
                result['rejected_options'].append(key)
    if idx + 1 >= len(pieces):
        result['invalid'] = True
        return result
    result['dist'] = pieces[idx + 1].strip()
    result['comps'] = [p.strip() for p in pieces[idx + 2:]]
    return result

def normalize_deb_source_line(line):
    s = line.strip()
    if not s or s.startswith('#'):
        return ''
    comment_i = s.find('#')
    if comment_i > 0:
        s = s[:comment_i].rstrip()
    if not s.startswith('deb'):
        return ''
    return s

def count_nonascii_comments(lines):
    n = 0
    for line in lines:
        s = line.rstrip('\n')
        if not s.strip():
            continue
        if s.lstrip().startswith('#'):
            for ch in s:
                if ord(ch) > 127:
                    n += 1
                    break
            continue
        comment_i = s.find('#')
        if comment_i > 0:
            for ch in s[comment_i:]:
                if ord(ch) > 127:
                    n += 1
                    break
    return n

path = os.environ['SOURCES_FILE']
expected = os.environ.get('EXPECTED_SUITES', '').split()
comps_expected = os.environ.get('EXPECTED_COMPONENTS', 'main universe').split()

try:
    with open(path, 'rb') as fh:
        raw = fh.read()
except (OSError, IOError) as exc:
    print('DISTUPGRADE_SOURCE_INPUT_ENCODING=UTF-8')
    print('DISTUPGRADE_SOURCE_DECODE_RESULT=FAIL')
    print('DISTUPGRADE_SOURCE_NONASCII_COMMENT_COUNT=0')
    print('DISTUPGRADE_VALID_SOURCE_COUNT=0')
    print('DISTUPGRADE_INVALID_SOURCE_COUNT=0')
    print('ERROR=FAIL_DISTUPGRADE_SOURCE_INVALID')
    print('DECODE_PATH=%s' % path)
    print('DECODE_DETAIL=cannot read: %s' % exc)
    sys.exit(4)

enc_label = 'UTF-8-SIG' if raw.startswith(b'\xef\xbb\xbf') else 'UTF-8'
print('DISTUPGRADE_SOURCE_INPUT_ENCODING=%s' % enc_label)
try:
    text = raw.decode('utf-8-sig')
except UnicodeDecodeError as exc:
    start = getattr(exc, 'start', None)
    line_no = (raw[:start].count(b'\n') + 1) if start is not None else None
    print('DISTUPGRADE_SOURCE_DECODE_RESULT=FAIL')
    print('DISTUPGRADE_SOURCE_NONASCII_COMMENT_COUNT=0')
    print('DISTUPGRADE_VALID_SOURCE_COUNT=0')
    print('DISTUPGRADE_INVALID_SOURCE_COUNT=0')
    print('ERROR=FAIL_DISTUPGRADE_SOURCE_TEXT_DECODE')
    print('DECODE_PATH=%s' % path)
    print('DECODE_LINE=%s' % line_no)
    print('DECODE_BYTE_OFFSET=%s' % start)
    print('DECODE_DETAIL=%s' % exc)
    sys.exit(5)

lines = text.splitlines()
nonascii = count_nonascii_comments(lines)
print('DISTUPGRADE_SOURCE_NONASCII_COMMENT_COUNT=%d' % nonascii)
print('DISTUPGRADE_SOURCE_DECODE_RESULT=PASS')

valid = invalid = signed_by = trusted_yes = 0
found = {}
for line in lines:
    s = normalize_deb_source_line(line)
    if not s:
        continue
    if 'trusted=yes' in s.replace(' ', ''):
        trusted_yes += 1
    parsed = distupgrade_source_entry_valid(s)
    if parsed['invalid']:
        invalid += 1
        if 'signed-by' in parsed['rejected_options']:
            signed_by += 1
        continue
    valid += 1
    found.setdefault(parsed['dist'], set()).update(parsed['comps'])

ok = True
for suite in expected:
    key = 'DISTUPGRADE_SOURCE_VALID_%s' % suite.replace('-', '_')
    comps = found.get(suite) or set()
    if suite in found and all(c in comps for c in comps_expected):
        print('%s=PASS' % key)
    else:
        print('%s=FAIL' % key)
        ok = False
print('DISTUPGRADE_VALID_SOURCE_COUNT=%d' % valid)
print('DISTUPGRADE_INVALID_SOURCE_COUNT=%d' % invalid)
if signed_by:
    print('ERROR=FAIL_SIGNED_BY_PRESENT_IN_DISTUPGRADE_SOURCE')
    sys.exit(2)
if trusted_yes:
    print('ERROR=FAIL_TRUSTED_YES_FORBIDDEN')
    sys.exit(4)
if expected and valid != len(expected):
    print('ERROR=FAIL_DISTUPGRADE_SOURCE_COUNT_MISMATCH')
    sys.exit(3)
if not ok or invalid:
    print('ERROR=FAIL_DISTUPGRADE_SOURCE_INVALID')
    sys.exit(4)
print('DISTUPGRADE_SOURCE_COMPATIBILITY=PASS')
sys.exit(0)
PY
  )"
  py_rc=$?
  set -e
  while IFS= read -r line; do
    [[ -n "$line" ]] && log INFO "$line"
  done <<<"$py_out"
  err_token="$(printf '%s\n' "$py_out" | sed -n 's/^ERROR=//p' | tail -n 1)"
  case "$py_rc" in
    0)
      LAST_DISTUPGRADE_SOURCE_ERROR=""
      return 0
      ;;
    2)
      LAST_DISTUPGRADE_SOURCE_ERROR="${err_token:-FAIL_SIGNED_BY_PRESENT_IN_DISTUPGRADE_SOURCE}"
      ;;
    3)
      LAST_DISTUPGRADE_SOURCE_ERROR="${err_token:-FAIL_DISTUPGRADE_SOURCE_COUNT_MISMATCH}"
      ;;
    5)
      LAST_DISTUPGRADE_SOURCE_ERROR="${err_token:-FAIL_DISTUPGRADE_SOURCE_TEXT_DECODE}"
      ;;
    4|*)
      LAST_DISTUPGRADE_SOURCE_ERROR="${err_token:-FAIL_DISTUPGRADE_SOURCE_INVALID}"
      ;;
  esac
  printf '%s\n' "$LAST_DISTUPGRADE_SOURCE_ERROR" >"$err_file"
  log ERROR "$LAST_DISTUPGRADE_SOURCE_ERROR"
  return "$py_rc"
}

validate_target_pocket_components_from_mirror() {
  # HTTP-check that each target suite exposes main+universe Packages (non-empty via Release).
  local repo="${MIRROR_BASE}/hops/${PIN_HOP}/ubuntu"
  local suite comp code ok=1
  for suite in $PIN_TARGET_SUITES; do
    local missing=0
    for comp in $PIN_COMPONENTS; do
      code="$(http_code "${repo}/dists/${suite}/${comp}/binary-amd64/Packages.gz")"
      if [[ "$code" != "200" ]]; then
        code="$(http_code "${repo}/dists/${suite}/${comp}/binary-amd64/Packages")"
      fi
      if [[ "$code" != "200" ]]; then
        missing=1
        log ERROR "TARGET_POCKET=${suite} COMPONENTS=${comp} RESULT=FAIL"
        ok=0
      fi
    done
    if [[ "$missing" -eq 0 ]]; then
      log INFO "TARGET_POCKET=${suite} COMPONENTS=$(echo $PIN_COMPONENTS | tr ' ' ',') RESULT=PASS"
    else
      log ERROR "FAIL_TARGET_POCKET_COMPONENT_EMPTY_OR_MISMATCH suite=${suite}"
    fi
  done
  [[ "$ok" -eq 1 ]]
}

collect_pre_dro_evidence() {
  local stamp dest
  stamp="$(date -u '+%Y%m%dT%H%M%SZ')"
  dest="$(hostpath ${STATE_ROOT}/evidence/${stamp}/pre-dro)"
  mkdir -p "$dest"
  cp -a "$(hostpath /etc/apt/sources.list)" "$dest/host-sources.list" 2>/dev/null || true
  cp -a "$(hostpath "$DISTUPGRADE_SOURCES_PATH")" "$dest/distupgrade-target.sources.list" 2>/dev/null || true
  printf '%s\n' "$PIN_KEY_FINGERPRINT" >"$dest/trusted-key-fingerprint.txt"
  if [[ -z "$TEST_ROOT" ]]; then
    apt-cache policy >"$dest/apt-cache-policy.txt" 2>/dev/null || true
  fi
  {
    echo "DISTUPGRADE_SOURCE_COMPATIBILITY=see logs"
    echo "LEGACY_APT_KEYRING_PATH=${LEGACY_APT_KEYRING_PATH}"
    echo "LEGACY_APT_KEY_FINGERPRINT=${PIN_KEY_FINGERPRINT}"
  } >"$dest/repository-semantic-validation.txt"
  log INFO "PRE_DRO_EVIDENCE=${dest}"
}

# --- ASCII-only legacy config helpers (Xenial Python 3.5 / locale-safe) ---
# Generated files read by UpdateManager/configparser MUST be ASCII-only.
# Do not rely on LC_ALL=C.UTF-8; Xenial may lack that locale.

assert_ascii_file() {
  # Fail if any byte outside tab/LF/CR/printable ASCII (0x20-0x7e).
  # Args: path [fail_token]
  local path="$1"
  local fail_token="${2:-FAIL_META_RELEASE_CONFIG_NON_ASCII}"
  local py_out rc=0
  [[ -f "$path" ]] || {
    log ERROR "${fail_token}"
    log ERROR "FILE=${path}"
    log ERROR "REASON=missing"
    return 1
  }
  set +e
  py_out="$(
    LC_ALL=C LANG=C python3 - "$path" <<'PY'
import sys
path = sys.argv[1]
data = open(path, "rb").read()
for i, b in enumerate(data):
    if b in (9, 10, 13):
        continue
    if 32 <= b <= 126:
        continue
    sys.stdout.write("OFFSET=%d\nBYTE_HEX=%02x\n" % (i, b))
    sys.exit(1)
sys.exit(0)
PY
  )"
  rc=$?
  set -e
  if [[ "$rc" -ne 0 ]]; then
    log ERROR "${fail_token}"
    log ERROR "FILE=${path}"
    printf '%s\n' "$py_out" | while IFS= read -r line; do
      [[ -n "$line" ]] && log ERROR "$line"
    done
    return 1
  fi
  return 0
}

render_update_manager_meta_release() {
  # Render ASCII-only /etc/update-manager/meta-release content to dest.
  # Args: meta_local_path dest_path [hop_label]
  local meta_local="$1"
  local dest="$2"
  local hop_label="${3:-$PIN_HOP}"
  # hop_label must be ASCII (e.g. xenial-to-bionic); never use UTF-8 arrows.
  cat >"$dest" <<EOF
# Managed by stellar offline ${hop_label} upgrade
[METARELEASE]
URI = file://${meta_local}
URI_LTS = file://${meta_local}
URI_UNSTABLE_POSTFIX = -development
URI_PROPOSED_POSTFIX = -proposed
EOF
}

validate_meta_release_config_file() {
  # ASCII + configparser + METARELEASE URI/URI_LTS checks.
  # Args: path [require_uri_targets=0|1]
  local path="$1"
  local require_targets="${2:-0}"
  local py_rc=0 py_out uri uri_lts

  assert_ascii_file "$path" "FAIL_META_RELEASE_CONFIG_NON_ASCII" \
    || die "$EC_META_ASCII" "FAIL_META_RELEASE_CONFIG_NON_ASCII"
  log INFO "META_RELEASE_ASCII_VALIDATION=PASS"

  set +e
  py_out="$(
    LC_ALL=C LANG=C python3 - "$path" <<'PY'
from __future__ import print_function
import sys
try:
    import configparser
except ImportError:
    import ConfigParser as configparser  # type: ignore
path = sys.argv[1]
raw = open(path, "rb").read()
try:
    text = raw.decode("ascii")
except UnicodeDecodeError as exc:
    print("FAIL_META_RELEASE_CONFIG_NON_ASCII")
    print("OFFSET=%s" % getattr(exc, "start", "?"))
    sys.exit(2)
try:
    p = configparser.ConfigParser()
    if hasattr(p, "read_string"):
        p.read_string(text)
    else:
        from io import StringIO
        p.readfp(StringIO(text))  # type: ignore
except Exception as exc:
    print("FAIL_META_RELEASE_CONFIG_PARSE")
    print("ERROR=%s" % exc)
    sys.exit(3)
if not p.has_section("METARELEASE"):
    print("FAIL_META_RELEASE_CONFIG_PARSE")
    print("ERROR=missing METARELEASE section")
    sys.exit(3)
uri = ""
uri_lts = ""
try:
    if hasattr(p, "get"):
        uri = p.get("METARELEASE", "URI")
        uri_lts = p.get("METARELEASE", "URI_LTS")
except Exception as exc:
    print("FAIL_META_RELEASE_URI_INVALID")
    print("ERROR=%s" % exc)
    sys.exit(4)
if not uri or not uri_lts:
    print("FAIL_META_RELEASE_URI_INVALID")
    print("ERROR=empty URI or URI_LTS")
    sys.exit(4)
print("URI=%s" % uri)
print("URI_LTS=%s" % uri_lts)
sys.exit(0)
PY
  )"
  py_rc=$?
  set -e

  case "$py_rc" in
    0)
      log INFO "META_RELEASE_CONFIGPARSER_VALIDATION=PASS"
      ;;
    2)
      log ERROR "FAIL_META_RELEASE_CONFIG_NON_ASCII"
      printf '%s\n' "$py_out" | while IFS= read -r line; do [[ -n "$line" ]] && log ERROR "$line"; done
      die "$EC_META_ASCII" "FAIL_META_RELEASE_CONFIG_NON_ASCII"
      ;;
    3)
      log ERROR "FAIL_META_RELEASE_CONFIG_PARSE"
      printf '%s\n' "$py_out" | while IFS= read -r line; do [[ -n "$line" ]] && log ERROR "$line"; done
      die "$EC_META" "FAIL_META_RELEASE_CONFIG_PARSE"
      ;;
    *)
      log ERROR "FAIL_META_RELEASE_URI_INVALID"
      printf '%s\n' "$py_out" | while IFS= read -r line; do [[ -n "$line" ]] && log ERROR "$line"; done
      die "$EC_META" "FAIL_META_RELEASE_URI_INVALID"
      ;;
  esac

  uri="$(printf '%s\n' "$py_out" | sed -n 's/^URI=//p' | head -1)"
  uri_lts="$(printf '%s\n' "$py_out" | sed -n 's/^URI_LTS=//p' | head -1)"

  if printf '%s\n%s\n' "$uri" "$uri_lts" | grep -qiE '(archive|security|old-releases|changelogs)\.ubuntu\.com'; then
    log ERROR "FAIL_META_RELEASE_URI_INVALID"
    log ERROR "REASON=external_canonical_host"
    die "$EC_META" "FAIL_META_RELEASE_URI_INVALID"
  fi
  case "$uri" in
    file://*) ;;
    *)
      log ERROR "FAIL_META_RELEASE_URI_INVALID"
      log ERROR "REASON=URI_must_be_file"
      die "$EC_META" "FAIL_META_RELEASE_URI_INVALID"
      ;;
  esac
  case "$uri_lts" in
    file://*) ;;
    *)
      log ERROR "FAIL_META_RELEASE_URI_INVALID"
      log ERROR "REASON=URI_LTS_must_be_file"
      die "$EC_META" "FAIL_META_RELEASE_URI_INVALID"
      ;;
  esac

  if [[ "$require_targets" == "1" ]]; then
    local target
    target="${uri#file://}"
    [[ -f "$target" ]] || {
      log ERROR "FAIL_META_RELEASE_URI_INVALID"
      log ERROR "REASON=URI_target_missing"
      log ERROR "TARGET=${target}"
      die "$EC_META" "FAIL_META_RELEASE_URI_INVALID"
    }
    target="${uri_lts#file://}"
    [[ -f "$target" ]] || {
      log ERROR "FAIL_META_RELEASE_URI_INVALID"
      log ERROR "REASON=URI_LTS_target_missing"
      log ERROR "TARGET=${target}"
      die "$EC_META" "FAIL_META_RELEASE_URI_INVALID"
    }
    # Dist-format runtime meta is not configparser INI; do not force ASCII on
    # upstream Description text. External URL check already ran at build time.
  fi
  log INFO "META_RELEASE_URI_VALIDATION=PASS"
}

build_runtime_meta_release_content() {
  # Write runtime meta-release-lts body to dest (no update-manager INI).
  local work="$1"
  local dest="$2"
  local offline_meta
  offline_meta="$work/meta-release-lts"
  if [[ -n "$TEST_ROOT" && ( "$PIN_KEY_FINGERPRINT" == "DEADBEEF" || "${DP_OFFLINE_FAKE_MIRROR_TRUST:-}" == "1" ) ]]; then
    cat >"$dest" <<EOF
Dist: ${PIN_TARGET_CODENAME}
Name: Ubuntu ${PIN_TARGET_VERSION} LTS
Version: ${PIN_TARGET_VERSION}
Date: Thu, 01 Jan 1970 00:00:00 UTC
Supported: 1
Description: Stub offline meta-release for TEST_ROOT
Release-File: ${MIRROR_BASE}/hops/${PIN_HOP}/ubuntu/dists/${PIN_TARGET_CODENAME}/Release
ReleaseNotes: file://$(hostpath ${STATE_ROOT}/announcements/ReleaseAnnouncement)
UpgradeTool: ${MIRROR_BASE}/hops/${PIN_HOP}/ubuntu/dists/${PIN_TARGET_CODENAME}/main/dist-upgrader-all/current/${PIN_TARGET_CODENAME}.tar.gz
UpgradeToolSignature: ${MIRROR_BASE}/hops/${PIN_HOP}/ubuntu/dists/${PIN_TARGET_CODENAME}/main/dist-upgrader-all/current/${PIN_TARGET_CODENAME}.tar.gz.gpg
EOF
  else
    sed -E \
      -e "s|^(ReleaseNotes): .*|\\1: file://$(hostpath ${STATE_ROOT}/announcements/ReleaseAnnouncement)|" \
      -e "/^ReleaseNotesHtml:/d" \
      "$offline_meta" >"$dest"
    if grep -qiE '(archive|security|old-releases|changelogs)\.ubuntu\.com' "$dest"; then
      die "$EC_META" "runtime meta-release still has external URLs"
    fi
    grep -q 'UpgradeTool: http' "$dest" || die "$EC_META" "UpgradeTool missing in runtime meta-release"
  fi
}

validate_meta_release_preview() {
  # Pre-confirmation: render final INI to a temp file and validate (no /etc install).
  local work="$1"
  local preview_dir meta_preview ini_preview meta_local_logical
  preview_dir="$(mktemp -d /tmp/stellar-meta-preview.XXXXXX)"
  meta_preview="${preview_dir}/meta-release-lts.runtime"
  ini_preview="${preview_dir}/meta-release"
  meta_local_logical="$(hostpath ${STATE_ROOT}/meta-release-lts.runtime)"
  build_runtime_meta_release_content "$work" "$meta_preview"
  # Preview INI uses the eventual runtime path (targets checked after install).
  render_update_manager_meta_release "$meta_local_logical" "$ini_preview" "$PIN_HOP"
  validate_meta_release_config_file "$ini_preview" 0
  if grep -qiE '(archive|security|old-releases|changelogs)\.ubuntu\.com' "$meta_preview"; then
    rm -rf "$preview_dir"
    die "$EC_META" "preview runtime meta-release contains external URLs"
  fi
  rm -rf "$preview_dir"
  log INFO "META_RELEASE_PRECONFIRM_VALIDATION=PASS"
}

apply_meta_release() {
  local work="$1"
  local offline_meta um_dir meta_local ini_tmp
  offline_meta="$(hostpath ${STATE_ROOT}/meta-release-lts)"
  mkdir -p "$(hostpath "$STATE_ROOT")" "$(hostpath ${STATE_ROOT}/announcements)"
  install -m 0644 "$work/meta-release-lts" "$offline_meta"
  install -m 0644 "$work/ReleaseAnnouncement" "$(hostpath ${STATE_ROOT}/announcements/ReleaseAnnouncement)"

  meta_local="$(hostpath ${STATE_ROOT}/meta-release-lts.runtime)"
  build_runtime_meta_release_content "$work" "$meta_local"

  um_dir="$(hostpath /etc/update-manager)"
  mkdir -p "$um_dir"
  ini_tmp="${um_dir}/meta-release.stellar-new.$$"
  render_update_manager_meta_release "$meta_local" "$ini_tmp" "$PIN_HOP"
  validate_meta_release_config_file "$ini_tmp" 1
  mv -f "$ini_tmp" "${um_dir}/meta-release"
  validate_meta_release_config_file "${um_dir}/meta-release" 1
  log INFO "META_RELEASE_CONFIG_REGENERATED=YES"

  if [[ -f "${um_dir}/release-upgrades" ]]; then
    if grep -qE '^Prompt=' "${um_dir}/release-upgrades"; then
      sed -i 's/^Prompt=.*/Prompt=lts/' "${um_dir}/release-upgrades"
    else
      printf '\nPrompt=lts\n' >>"${um_dir}/release-upgrades"
    fi
  else
    cat >"${um_dir}/release-upgrades" <<EOF
[DEFAULT]
Prompt=lts
EOF
  fi
  assert_ascii_file "${um_dir}/release-upgrades" "FAIL_META_RELEASE_CONFIG_NON_ASCII" \
    || die "$EC_META_ASCII" "FAIL_META_RELEASE_CONFIG_NON_ASCII release-upgrades"
}

change_login_shells() {
  local stamp="$1"
  local rec evidence_file passwd_file
  local changed_at user shell line after action
  local root_before="" aella_before="" root_action="" aella_action=""
  rec="$(hostpath "${BACKUP_ROOT}/${stamp}/passwd/shell-changes.tsv")"
  evidence_file="$(hostpath "${BACKUP_ROOT}/${stamp}/passwd/shell-automation.txt")"
  mkdir -p "$(dirname "$rec")"
  : >"$rec"
  changed_at="$(utc_now 2>/dev/null || date -u '+%Y-%m-%dT%H:%M:%SZ')"
  passwd_file="$(hostpath /etc/passwd)"

  _login_shell_read() {
    local u="$1" l
    if [[ -n "$TEST_ROOT" ]]; then
      l="$(grep -E "^${u}:" "$passwd_file" 2>/dev/null || true)"
      [[ -n "$l" ]] || return 1
      printf '%s' "$(printf '%s' "$l" | cut -d: -f7)"
      return 0
    fi
    getent passwd "$u" >/dev/null 2>&1 || return 1
    getent passwd "$u" | cut -d: -f7
  }

  _login_shell_set() {
    local u="$1"
    if [[ -n "$TEST_ROOT" ]]; then
      awk -F: -v u="$u" 'BEGIN{OFS=":"} $1==u {$7="/bin/bash"} {print}' \
        "$passwd_file" >"${passwd_file}.new"
      mv -f "${passwd_file}.new" "$passwd_file"
      return 0
    fi
    if command -v chsh >/dev/null 2>&1; then
      if chsh -s /bin/bash "$u"; then
        return 0
      fi
    fi
    if command -v usermod >/dev/null 2>&1; then
      usermod -s /bin/bash "$u"
      return $?
    fi
    return 1
  }

  if ! _login_shell_read root >/dev/null; then
    log ERROR "LOGIN_SHELL_ROOT_ACCOUNT=FAIL"
    log ERROR "LOGIN_SHELL_AUTOMATION=FAIL"
    die "$EC_INTERNAL" "FAIL_LOGIN_SHELL_ROOT_ACCOUNT_MISSING"
  fi
  log INFO "LOGIN_SHELL_ROOT_ACCOUNT=PASS"
  if ! _login_shell_read aella >/dev/null; then
    log ERROR "LOGIN_SHELL_AELLA_ACCOUNT=FAIL"
    log ERROR "LOGIN_SHELL_AUTOMATION=FAIL"
    die "$EC_INTERNAL" "FAIL_LOGIN_SHELL_AELLA_ACCOUNT_MISSING"
  fi
  log INFO "LOGIN_SHELL_AELLA_ACCOUNT=PASS"

  if [[ -n "$TEST_ROOT" ]]; then
    if [[ ! -x "$(hostpath /bin/bash)" && ! -x /bin/bash ]]; then
      # Fixture hosts may lack a real /bin/bash under TEST_ROOT; require host bash.
      if [[ ! -x /bin/bash ]]; then
        log ERROR "LOGIN_SHELL_BASH_EXECUTABLE=FAIL"
        log ERROR "LOGIN_SHELL_AUTOMATION=FAIL"
        die "$EC_INTERNAL" "FAIL_LOGIN_SHELL_BASH_MISSING"
      fi
    fi
  else
    if [[ ! -f /bin/bash || ! -x /bin/bash ]]; then
      log ERROR "LOGIN_SHELL_BASH_EXECUTABLE=FAIL"
      log ERROR "LOGIN_SHELL_AUTOMATION=FAIL"
      die "$EC_INTERNAL" "FAIL_LOGIN_SHELL_BASH_MISSING"
    fi
  fi
  log INFO "LOGIN_SHELL_BASH_EXECUTABLE=PASS"

  for user in root aella; do
    shell="$(_login_shell_read "$user")" || {
      log ERROR "LOGIN_SHELL_AUTOMATION=FAIL"
      die "$EC_INTERNAL" "FAIL_LOGIN_SHELL_READ_${user}"
    }
    printf '%s\t%s\n' "$user" "$shell" >>"$rec"
    if [[ "$user" == "root" ]]; then
      root_before="$shell"
    else
      aella_before="$shell"
    fi
    log INFO "LOGIN_SHELL_${user^^}_BEFORE=${shell}"
    if [[ "$shell" == "/bin/bash" ]]; then
      action="UNCHANGED"
      log INFO "LOGIN_SHELL_${user^^}_ACTION=UNCHANGED"
    else
      if [[ "$shell" != "/usr/bin/aella_cli" && "$shell" != *aella_cli* ]]; then
        log WARN "unexpected ${user} shell ${shell}; setting /bin/bash for upgrade safety"
      fi
      if [[ -n "$TEST_ROOT" && "${DP_OFFLINE_FAKE_SHELL_CHANGE_FAIL:-}" == "1" ]]; then
        log ERROR "LOGIN_SHELL_AUTOMATION=FAIL"
        die "$EC_INTERNAL" "FAIL_LOGIN_SHELL_CHANGE_${user}"
      fi
      if [[ -n "$TEST_ROOT" && "${DP_OFFLINE_FAKE_SHELL_CHSH_FAIL:-}" == "1" ]]; then
        # Force usermod path in fixture mode by rewriting passwd directly (usermod success).
        :
      fi
      if ! _login_shell_set "$user"; then
        log ERROR "LOGIN_SHELL_AUTOMATION=FAIL"
        die "$EC_INTERNAL" "FAIL_LOGIN_SHELL_CHANGE_${user}"
      fi
      if [[ -n "$TEST_ROOT" && "${DP_OFFLINE_FAKE_SHELL_NOOP_SUCCESS:-}" == "1" ]]; then
        # Command "succeeded" but leave shell unchanged to exercise post-change verify.
        awk -F: -v u="$user" -v s="$shell" 'BEGIN{OFS=":"} $1==u {$7=s} {print}' \
          "$passwd_file" >"${passwd_file}.new"
        mv -f "${passwd_file}.new" "$passwd_file"
      fi
      action="CHANGED"
      log INFO "LOGIN_SHELL_${user^^}_ACTION=CHANGED"
    fi
    after="$(_login_shell_read "$user")" || after=""
    log INFO "LOGIN_SHELL_${user^^}_AFTER=${after}"
    if [[ "$after" != "/bin/bash" ]]; then
      log ERROR "LOGIN_SHELL_AUTOMATION=FAIL"
      die "$EC_INTERNAL" "FAIL_LOGIN_SHELL_VERIFY_${user}"
    fi
    if [[ "$user" == "root" ]]; then
      root_action="$action"
    else
      aella_action="$action"
    fi
  done

  {
    printf 'changed_at=%s\n' "$changed_at"
    printf 'root_original_shell=%s\n' "$root_before"
    printf 'aella_original_shell=%s\n' "$aella_before"
    printf 'root_action=%s\n' "$root_action"
    printf 'aella_action=%s\n' "$aella_action"
    printf 'root_final_shell=/bin/bash\n'
    printf 'aella_final_shell=/bin/bash\n'
    printf 'result=PASS\n'
  } >"$evidence_file"

  log INFO "LOGIN_SHELL_AUTOMATION=PASS"
}

install_runner_and_units() {
  local work="$1"
  mkdir -p "$(hostpath /usr/local/sbin)" "$(hostpath /etc/systemd/system)"
  mkdir -p "$(hostpath "$STATE_ROOT")"
  install -m 0755 /dev/stdin "$(hostpath "$RUNNER_PATH")" <<'RUNNER'
#!/usr/bin/env bash
# stellar-offline-os-upgrade-runner - Xenial→Bionic detached upgrade
# Bash 4.3 compatible. Does not inherit client shell env; loads EnvironmentFile.
set -eo pipefail
# Shared durable atomic write helpers for offline OS-upgrade clients.
# shellcheck shell=bash
# Injected at build time via the DURABLE_WRITE_HELPER template token.
# Prefer targeted file+directory fsync over unbounded global `sync`.
# Bash 4.3+/4.4 safe; requires python3 (standard on Bionic+ upgrade hosts).

DURABLE_WRITE_LOG_THRESHOLD_MS="${DURABLE_WRITE_LOG_THRESHOLD_MS:-500}"

_durable_now_ms() {
  python3 -c 'import time; print(int(time.time()*1000))' 2>/dev/null || echo 0
}

_durable_write_python() {
  # stdin → durable atomic replace at path. Args: path mode_or_empty preserve_owner(0|1)
  local dest="$1"
  local mode="${2:-}"
  local preserve_owner="${3:-1}"
  local content_file
  content_file="$(mktemp "${TMPDIR:-/tmp}/durable-content.XXXXXX")"
  cat >"$content_file"
  python3 - "$dest" "$mode" "$preserve_owner" "$content_file" <<'PY'
import errno
import os
import stat
import sys
import tempfile

dest = sys.argv[1]
mode_arg = sys.argv[2]
preserve_owner = sys.argv[3] == "1"
with open(sys.argv[4], "rb") as fh:
    data = fh.read()

parent = os.path.dirname(os.path.abspath(dest)) or "."
base = os.path.basename(dest)
os.makedirs(parent, mode=0o755, exist_ok=True)

existed = False
old_mode = None
old_uid = None
old_gid = None
if os.path.lexists(dest):
    if os.path.islink(dest):
        sys.stderr.write("DURABLE_WRITE_ERR=dest_is_symlink\n")
        sys.exit(2)
    st = os.lstat(dest)
    if not stat.S_ISREG(st.st_mode):
        sys.stderr.write("DURABLE_WRITE_ERR=dest_not_regular\n")
        sys.exit(2)
    existed = True
    old_mode = stat.S_IMODE(st.st_mode)
    old_uid = st.st_uid
    old_gid = st.st_gid

if mode_arg:
    mode = int(mode_arg, 8)
elif existed and old_mode is not None:
    mode = old_mode
else:
    mode = 0o644

fd = None
tmp_path = None
try:
    fd, tmp_path = tempfile.mkstemp(
        prefix="." + base + ".",
        suffix=".tmp",
        dir=parent,
    )
    written = 0
    view = memoryview(data)
    while written < len(data):
        n = os.write(fd, view[written:])
        if n <= 0:
            raise OSError(errno.EIO, "short write")
        written += n
    os.fsync(fd)
    os.fchmod(fd, mode)
    if preserve_owner and existed and old_uid is not None:
        try:
            os.fchown(fd, old_uid, old_gid)
        except OSError:
            pass
    os.close(fd)
    fd = None
    os.replace(tmp_path, dest)
    tmp_path = None
    dirfd = os.open(parent, os.O_RDONLY)
    try:
        os.fsync(dirfd)
    finally:
        os.close(dirfd)
except Exception as exc:
    if fd is not None:
        try:
            os.close(fd)
        except OSError:
            pass
    if tmp_path and os.path.lexists(tmp_path):
        try:
            os.unlink(tmp_path)
        except OSError:
            pass
    sys.stderr.write("DURABLE_WRITE_ERR=%s\n" % (exc,))
    sys.exit(1)
sys.exit(0)
PY
  local py_rc=$?
  rm -f "$content_file"
  return "$py_rc"
}

durable_fsync_path() {
  # Targeted fsync of an existing regular file and its parent directory.
  # Never falls back to unbounded global sync.
  local path="$1"
  python3 - "$path" <<'PY'
import os
import stat
import sys

path = sys.argv[1]
if not os.path.lexists(path):
    sys.exit(1)
if os.path.islink(path):
    sys.exit(2)
st = os.lstat(path)
parent = os.path.dirname(os.path.abspath(path)) or "."
if stat.S_ISREG(st.st_mode):
    fd = os.open(path, os.O_RDONLY)
    try:
        os.fsync(fd)
    finally:
        os.close(fd)
elif stat.S_ISDIR(st.st_mode):
    parent = path
else:
    sys.exit(2)
dirfd = os.open(parent, os.O_RDONLY)
try:
    os.fsync(dirfd)
finally:
    os.close(dirfd)
sys.exit(0)
PY
}

durable_atomic_write() {
  # durable_atomic_write <logical-name> <path> [mode]
  # Content from stdin. Optional mode octal (0600). Preserves owner when file exists.
  local logical="$1"
  local path="$2"
  local mode="${3:-}"
  local start_ms end_ms dur rc=0
  local errf

  if ! command -v python3 >/dev/null 2>&1; then
    if declare -F log >/dev/null 2>&1; then
      log ERROR "DURABLE_WRITE_BEGIN=${logical}"
      log ERROR "DURABLE_WRITE_PATH=${path}"
      log ERROR "DURABLE_WRITE_RESULT=FAIL"
      log ERROR "DURABLE_WRITE_DURATION_MS=0"
      log ERROR "DURABLE_WRITE_ERR=python3_missing"
    fi
    return 1
  fi

  start_ms="$(_durable_now_ms)"
  errf="$(mktemp "${TMPDIR:-/tmp}/durable-write.XXXXXX")"
  set +e
  _durable_write_python "$path" "$mode" 1 2>"$errf"
  rc=$?
  set -e
  end_ms="$(_durable_now_ms)"
  dur=$((end_ms - start_ms))
  if [[ "$dur" -lt 0 ]]; then
    dur=0
  fi

  if [[ "$rc" -ne 0 ]]; then
    if declare -F log >/dev/null 2>&1; then
      log ERROR "DURABLE_WRITE_BEGIN=${logical}"
      log ERROR "DURABLE_WRITE_PATH=${path}"
      log ERROR "DURABLE_WRITE_RESULT=FAIL"
      log ERROR "DURABLE_WRITE_DURATION_MS=${dur}"
      if [[ -s "$errf" ]]; then
        log ERROR "DURABLE_WRITE_ERR=$(tr '\n' ' ' <"$errf" | head -c 200)"
      fi
    fi
    rm -f "$errf"
    return 1
  fi

  if [[ "$dur" -ge "${DURABLE_WRITE_LOG_THRESHOLD_MS}" ]] && declare -F log >/dev/null 2>&1; then
    log INFO "DURABLE_WRITE_BEGIN=${logical}"
    log INFO "DURABLE_WRITE_PATH=${path}"
    log INFO "DURABLE_WRITE_RESULT=PASS"
    log INFO "DURABLE_WRITE_DURATION_MS=${dur}"
  fi
  rm -f "$errf"
  return 0
}

durable_atomic_write_string() {
  local logical="$1" path="$2" content="$3" mode="${4:-}"
  printf '%s' "$content" | durable_atomic_write "$logical" "$path" "$mode"
}

# Drop-in replacement for prior temp+rename helper (now durable).
atomic_write_file() {
  local dest="$1"
  durable_atomic_write "atomic_write_file" "$dest" || return 1
}


